// Üretilen dosya: tool/ozgun/uret.py. Bilim · Uzay, Güneş Sistemi ve gözlemsel astronomi (orta).
const ozScience3Orta = <(String, String, List<String>, String)>[
  ('Güneş\'in çekirdeğinde üretilen enerji, yüzeye yakın katmanlarda büyük gaz hücrelerinin yükselip alçalmasıyla taşınır. Bu taşınım bölgesine ne ad verilir?', 'Konvektif bölge', ['Işınım bölgesi ve onun üstündeki geçiş katmanı', 'Kromosfer', 'Taç'], 'Güneş\'in dış üçte birlik kısmında enerji, kaynayan çorbaya benzer biçimde gaz akımlarıyla, yani konveksiyonla taşınır. Daha içteki ışınım bölgesinde ise enerji fotonların soğurulup yeniden salınmasıyla ilerler.'),
  ('Güneş\'in dış atmosferi olan taç (korona), altındaki fotosferden çok daha sıcaktır. Bu durum neden ilginç bir bilmece olarak görülür?', 'Enerji kaynağından uzaklaştıkça sıcaklığın düşmesi beklenir', ['Taç tamamen katı maddeden oluşur', 'Taç yalnızca gece görülebilir', 'Taçta hiç manyetik alan bulunmaz'], 'Enerji çekirdekte üretildiği için dışa doğru sıcaklığın azalması beklenir; oysa taç milyonlarca kelvin sıcaklığa ulaşır. Bu ısınmanın manyetik süreçlerle ilgili olduğu düşünülür.'),
  ('Bir gözlemci birkaç gün boyunca Güneş lekelerinin Güneş diskinin bir kenarından öbür kenarına doğru kaydığını görüyor. Bu gözlem en doğrudan neyi gösterir?', 'Güneş\'in kendi ekseni çevresinde döndüğünü', ['Güneş\'in Dünya\'ya yaklaştığını', 'Güneş\'in kütlesinin azaldığını', 'Dünya\'nın eksen eğikliğinin her gün biraz değiştiğini'], 'Lekelerin disk üzerinde düzenli kayması, Güneş\'in kendi ekseni etrafında dönüşünün kanıtıdır. Güneş katı olmadığından ekvatoru kutuplarından daha hızlı döner.'),
  ('Güneş\'in ekvator bölgesi yaklaşık 25 günde, kutuplara yakın bölgeleri ise 30 günden uzun sürede döner. Bu durumun adı nedir?', 'Diferansiyel dönme', ['Eş zamanlı (senkron) dönme', 'Geri yönlü (retrograd) dönme', 'Presesyon'], 'Akışkan bir gaz küresi olan Güneş\'in farklı enlemleri farklı hızlarla döner; buna diferansiyel (farklı) dönme denir.'),
  ('Güneş\'te biriken manyetik enerjinin dakikalar içinde aniden salınarak X ışını dahil geniş bir tayfta parlamaya yol açtığı olaya ne denir?', 'Güneş patlaması', ['Güneş tutulması', 'Güneş lekesi minimumu ve sessiz dönem', 'Gün dönümü'], 'Güneş patlamaları manyetik alan çizgilerinin yeniden bağlanmasıyla enerjinin aniden açığa çıktığı olaylardır; kısa sürede çok büyük enerji yayarlar.'),
  ('Büyük bir taç kütle atımının (CME) Dünya\'ya ulaşması aşağıdakilerden hangisine yol açabilir?', 'Uydu ve elektrik şebekelerinde arızalara', ['Ay\'ın yörüngesinin değişmesine', 'Gelgit genliğinin her yerde iki katına çıkmasına', 'Mevsimlerin yer değiştirmesine'], 'Taç kütle atımlarının taşıdığı plazma ve manyetik alan, jeomanyetik fırtınalara yol açar; bu fırtınalar uydu elektroniğini, iletişimi ve uzun iletim hatlarını etkileyebilir.'),
  ('Güneş, Güneş sistemindeki toplam kütlenin yaklaşık yüzde kaçını oluşturur?', 'Yüzde 99,8', ['Yüzde 50', 'Yüzde 75', 'Yüzde 90 kadar'], 'Güneş\'in kütlesi tüm gezegenler, uydular ve küçük cisimlerin toplamından çok büyüktür; sistemin kütlesinin yaklaşık %99,8\'i Güneş\'tedir.'),
  ('Güneş\'in tayf sınıfı ve evrimsel durumu en iyi hangi ifadeyle tanımlanır?', 'Ana kolda bulunan G türü bir yıldız', ['Kırmızı dev evresindeki M türü bir yıldız', 'Beyaz cüce evresindeki A türü bir yıldız', 'Ana koldan ayrılmış O türü bir süperdev'], 'Güneş G2 V sınıfında, yani çekirdeğinde hidrojen yakan sarımsı bir ana kol yıldızıdır.'),
  ('Güneş\'in çekirdeğindeki sıcaklık yaklaşık kaç kelvindir?', '15 milyon K', ['5 800 K', 'Yaklaşık 150 000 K', '15 milyar K'], 'Çekirdekte sıcaklık yaklaşık 15 milyon kelvin, yoğunluk ise suyunkinin 150 katı kadardır; bu koşullar hidrojen kaynaşması için gereklidir.'),
  ('Gezegenlerin hepsinin Güneş çevresinde aynı yönde ve yaklaşık aynı düzlemde dolanması, Güneş sisteminin oluşumu hakkında ne düşündürür?', 'Tümünün aynı dönen diskten oluştuğunu', ['Her birinin ayrı yıldızlardan yakalandığını', 'Gezegenlerin Güneş\'ten daha yaşlı olduğunu', 'Düzlemin rastlantısal olarak oluştuğunu'], 'Dönen bir bulut çökerken yassılaşarak bir diske dönüşür; bu diskte oluşan gezegenler diskin dönüş yönünü ve düzlemini miras alır.'),
  ('İç gezegenlerin kayaç ve metalden, dış gezegenlerin ise büyük ölçüde gaz ve buzdan oluşmasının temel nedeni nedir?', 'Güneş\'e yakın bölgede buzların yoğuşamayacak kadar sıcak olması', ['Dış gezegenlerin daha geç oluşması', 'İç gezegenlerin sonradan yakalanması', 'Güneş rüzgârının dış bölgeye yalnızca hafif kayaçları taşıması'], 'Diskte "kar çizgisi" denen sınırın içinde su ve diğer buzlar katılaşamadı; yalnız metal ve silikatlar katılaşabildi. Dışarıda bol buz birikerek büyük çekirdekler ve gaz devleri oluştu.'),
  ('Bir gezegenin "gezegen" sayılması için Uluslararası Astronomi Birliği\'nin 2006\'da belirlediği ölçütlerden biri aşağıdakilerden hangisidir?', 'Yörünge çevresini başka cisimlerden temizlemiş olması', ['Çevresinde dolanan en az bir doğal uydusunun bulunması', 'Atmosferinin bulunması', 'Halka sistemine sahip olması'], '2006 tanımına göre gezegen Güneş\'in çevresinde dolanır, yaklaşık küresel olacak kadar kütlelidir ve yörünge çevresini temizlemiştir. Plüton son ölçütü sağlamadığı için cüce gezegen sayıldı.'),
  ('Merkür\'de gündüz ile gece arasındaki sıcaklık farkının çok büyük (yüzlerce derece) olmasının başlıca nedeni nedir?', 'Isıyı tutacak kalın bir atmosferinin bulunmaması', ['Yüzeyinin tamamen ışığı yansıtan bir buz tabakasıyla kaplı olması', 'Kendi ışığını üretmesi', 'Güneş\'ten çok uzak olması'], 'Atmosfer ısıyı dağıtıp tutan bir örtü görevi görür. Merkür\'ün atmosferi yok denecek kadar ince olduğundan gündüz yüzey ısınır, gece ise ısı hızla uzaya kaçar.'),
  ('Merkür Güneş çevresindeki bir turunu yaklaşık kaç Dünya gününde tamamlar?', '88', ['225', '365', '687'], 'Güneş\'e en yakın gezegen olan Merkür, Kepler\'in üçüncü yasasına uygun olarak en kısa yörünge dönemine sahiptir: yaklaşık 88 gün.'),
  ('Venüs\'ün kendi ekseni çevresinde dönüşü ile ilgili aşağıdakilerden hangisi doğrudur?', 'Çok yavaş ve geri yönde (doğudan batıya) döner', ['Merkür ile aynı hızda, ileri yönde döner', 'Dünya\'dan daha hızlı döner', 'Hiç dönmez, hep aynı yüzü Güneş\'e dönüktür'], 'Venüs\'ün eksen dönüşü yaklaşık 243 Dünya günü sürer ve diğer gezegenlerin çoğunun tersine yöndedir; bu yüzden Venüs\'te Güneş batıdan doğar.'),
  ('Venüs\'te bir yıldız günü (eksen dönüşü) yaklaşık 243 Dünya günü, bir yılı ise yaklaşık 225 Dünya günüdür. Bu bilgiye göre aşağıdaki ifadelerden hangisi doğrudur?', 'Venüs\'ün eksen dönüşü, Güneş çevresindeki turundan daha uzun sürer', ['Venüs\'ün yılı, eksen dönüşünün iki katıdır', 'Venüs bir yılda yaklaşık 243 kez döner', 'Venüs\'ün eksen dönüşü ve yılı eşittir, bu yüzden hep aynı yüzü Güneş\'e döner'], '243 gün 225 günden büyük olduğundan Venüs kendi çevresinde bir kez dönmeden Güneş çevresinde bir turunu tamamlar.'),
  ('Venüs\'ün yüzeyi neden optik teleskoplarla doğrudan görülemez ve bu sorun nasıl aşılmıştır?', 'Kalın bulutlar yüzeyi örter; radarla haritalanmıştır', ['Yüzeyi çok karanlıktır; kızılötesi lambalarla aydınlatılmıştır', 'Hep Güneş\'in arkasındadır; yalnızca tutulmalarda görülür', 'Yüzeyi sıvıdır; sonar ile ölçülmüştür'], 'Venüs\'ü tümüyle saran bulut tabakası görünür ışığı geçirmez. Radar dalgaları bulutlardan geçebildiği için Magellan gibi uzay araçları yüzeyi radarla haritalamıştır.'),
  ('Venüs\'ün atmosferi hakkında aşağıdakilerden hangisi doğrudur?', 'Büyük ölçüde karbondioksitten oluşur ve yüzey basıncı Dünya\'nınkinin yaklaşık 90 katıdır', ['Büyük ölçüde azottan oluşur ve basıncı Dünya\'nınkine eşittir', 'Büyük ölçüde hidrojenden oluşur ve çok seyrektir', 'Büyük ölçüde oksijenden oluşur ve yaşam için uygundur'], 'Venüs atmosferinin yaklaşık %96\'sı karbondioksittir; yüzeydeki basınç, Dünya okyanuslarında yaklaşık 900 m derinlikteki basınca eşdeğerdir.'),
  ('Dünya\'dan bakıldığında, Merkür\'ün zaman zaman Güneş diskinin önünden küçük kara bir nokta olarak geçtiği görülür. Bu olaya ne ad verilir?', 'Geçiş', ['Örtülme', 'Karşı konum ya da kavuşum', 'Halkalı tutulma ya da örtülme'], 'İç gezegenler Güneş ile Dünya arasından tam hizada geçtiğinde Güneş diskinin önünde kara bir benek gibi görülür; buna geçiş denir.'),
  ('Aşağıdaki gezegenlerden hangisi Dünya\'dan bakıldığında Güneş diskinin önünden geçerken görülebilir?', 'Venüs', ['Mars', 'Jüpiter', 'Satürn'], 'Bir gezegenin Güneş diskinin önünden geçmesi için Dünya ile Güneş arasında, yani Dünya yörüngesinin içinde dolanması gerekir. Seçeneklerden yalnızca Venüs bir iç gezegendir.'),
  ('Dünya, Güneş\'e en yakın noktasına (günberi) ocak ayının başında ulaşır. Bu bilgi, mevsimlerin uzaklıktan kaynaklanmadığını nasıl gösterir?', 'Kuzey Yarım Küre\'de kış, Dünya Güneş\'e en yakınken yaşanır', ['Ocak ayında iki yarım kürede de yaz yaşanır', 'Ocak ayında Güneş ışığı Dünya\'ya ulaşmaz', 'Günberide Dünya\'nın eksen eğikliği sıfırlanır'], 'Mevsimler uzaklıktan kaynaklansaydı ocakta her yerde yaz olurdu. Oysa ocakta Kuzey Yarım Küre kış, Güney Yarım Küre yaz yaşar; bu da eğikliğin belirleyici olduğunu gösterir.'),
  ('Dünya\'nın eksen eğikliği sıfır olsaydı aşağıdakilerden hangisi gerçekleşirdi?', 'Belirgin mevsimler olmaz, gece ile gündüz her yerde yıl boyu eşit olurdu', ['Bir yarım kürede sürekli gece, ötekinde sürekli gündüz olurdu', 'Mevsimler iki kat şiddetli yaşanırdı', 'Dünya\'nın yörüngesi Güneş\'ten uzaklaşırdı'], 'Eğiklik olmasaydı Güneş her gün ekvatorun tam üzerinde kalır, her enlemde gündüz süresi 12 saat olur ve yıl içinde ışınların geliş açısı değişmezdi.'),
  ('21 Haziran civarında Güneş öğle vakti hangi enlemdeki bir gözlemcinin tam tepesinde bulunur?', 'Yengeç Dönencesi (23,5° K)', ['Ekvator (0°)', 'Oğlak Dönencesi (23,5° G)', 'Kuzey Kutup Dairesi (66,5° K)'], 'Yaz gün dönümünde Kuzey Yarım Küre Güneş\'e en çok eğiktir ve öğle Güneşi Yengeç Dönencesi üzerinde dik açıyla parlar.'),
  ('Ekinoks (gün-gece eşitliği) günlerinde Güneş hangi noktalardan doğar ve batar?', 'Tam doğudan doğar, tam batıdan batar', ['Kuzeydoğudan doğar, kuzeybatıdan batar', 'Güneydoğudan doğar, güneybatıdan batar', 'Tam güneyden doğar, tam kuzeyden batar'], 'Ekinokslarda Güneş gök ekvatoru üzerindedir; gök ekvatoru ufku tam doğu ve tam batı noktalarında kestiği için Güneş bu noktalardan doğup batar.'),
  ('Ay\'ın yüzeyinde çıplak gözle görülen geniş, koyu renkli düzlüklere ne ad verilir ve bunlar nasıl oluşmuştur?', 'Maria (denizler); eski bazalt lav akıntılarıyla', ['Okyanuslar; donmuş suyla', 'Çöller; kum fırtınalarıyla', 'Buzullar; eskiden yüzeyi örten buz tabakalarının erimesiyle'], 'Eski gözlemciler bu koyu bölgeleri deniz sandığı için Latince "mare" (çoğulu maria) adı verildi. Aslında büyük çarpma havzalarını dolduran katılaşmış bazalt lavlardır.'),
  ('Ay\'ın oluşumunu açıklayan ve en yaygın kabul gören kuram hangisidir?', 'Genç Dünya\'ya Mars büyüklüğünde bir cismin çarpması', ['Ay\'ın Dünya\'nın yanından geçerken onun çekimiyle sonradan yakalanması', 'Ay\'ın Güneş\'ten kopan bir parça olması', 'Ay\'ın Jüpiter\'den fırlatılması'], 'Dev çarpma kuramına göre yaklaşık 4,5 milyar yıl önce Theia adı verilen bir cisim Dünya\'ya çarptı; saçılan madde Dünya çevresinde birikerek Ay\'ı oluşturdu.'),
  ('Ay\'ın Dünya\'ya göre çapı ve uzaklığı için aşağıdakilerden hangisi doğrudur?', 'Çapı Dünya\'nın yaklaşık dörtte biri, uzaklığı yaklaşık 384 000 km\'dir', ['Çapı Dünya\'nın yarısı, uzaklığı yaklaşık 38 000 km\'dir', 'Çapı Dünya\'nın onda biri, uzaklığı yaklaşık 3,8 milyon km\'dir', 'Çapı Dünya\'ya eşit, uzaklığı yaklaşık 150 milyon km\'dir'], 'Ay\'ın çapı yaklaşık 3 475 km, Dünya\'nınki yaklaşık 12 742 km\'dir; oran dörtte bire yakındır. Ortalama uzaklık yaklaşık 384 400 km\'dir.'),
  ('Ay\'ın Dünya\'dan görülmeyen yüzü için "karanlık yüz" demek neden yanlıştır?', 'O yüz de Güneş\'ten ışık alır; yalnızca Dünya\'dan görünmez', ['O yüz Güneş\'e hiç dönmez, ama kendi ışığıyla yine de parlak kalır', 'O yüz kendi ışığını üretir', 'O yüz sürekli Dünya\'nın gölgesindedir'], 'Ay döndüğü için her iki yarı küresi de sırayla gündüz ve gece yaşar. Yeni Ay evresinde, bize görünmeyen yüz tamamen aydınlanmıştır.'),
  ('Ay\'ın yüzeyini kaplayan ince taneli, keskin köşeli toz ve kaya kırıntısı tabakasına ne ad verilir?', 'Regolit', ['Humus ya da toprak', 'Lös', 'Tüf'], 'Regolit, sürekli göktaşı çarpmalarıyla kayaçların parçalanıp öğütülmesi sonucu oluşan gevşek yüzey örtüsüdür.'),
  ('Ay\'ın Dünya çevresindeki yörüngesi tam bir çember değildir. Ay\'ın Dünya\'ya en yakın olduğu noktaya ne ad verilir?', 'Yerberi (perige)', ['Yeröte (apoje)', 'Günberi', 'Günöte'], 'Dünya çevresindeki eliptik yörüngelerde en yakın nokta yerberi, en uzak nokta yeröte olarak adlandırılır. Güneş çevresindeki yörüngede ise günberi ve günöte terimleri kullanılır.'),
  ('Dolunay evresindeki Ay hangi saatlerde doğar?', 'Güneş batarken', ['Güneş doğarken, sabahın erken saatlerinde', 'Öğle vakti', 'Gece yarısı'], 'Dolunay Güneş\'in tam karşısında olduğundan Güneş batarken doğuda yükselir, gece yarısı en yüksek noktasına çıkar ve Güneş doğarken batar.'),
  ('Bir gözlemci akşam saatlerinde, Güneş battıktan kısa süre sonra batı ufkunda ince bir hilal görüyor. Ay hangi evrededir?', 'Büyüyen hilal', ['Küçülen hilal', 'Dolunay', 'Son dördün'], 'Yeni Ay\'dan birkaç gün sonra Ay Güneş\'in biraz doğusunda olur ve Güneş battıktan sonra batı ufkunda ince bir hilal olarak görünür. Küçülen hilal ise sabaha karşı doğu ufkunda görülür.'),
  ('Kuzey Yarım Küre\'den bakıldığında ilk dördün evresinde Ay\'ın hangi yarısı aydınlık görünür?', 'Sağ yarısı', ['Sol yarısı', 'Üst yarısı', 'Alt yarısı'], 'İlk dördünde Ay, Güneş\'in 90° doğusundadır ve Kuzey Yarım Küre\'den bakıldığında sağ (batıya bakan) yarısı aydınlıktır. Son dördünde ise sol yarı aydınlıktır.'),
  ('Her ay Yeni Ay ve Dolunay olmasına karşın her ay tutulma gerçekleşmez. Bunun nedeni nedir?', 'Ay\'ın yörünge düzlemi Dünya\'nın yörünge düzlemine göre yaklaşık 5° eğiktir', ['Ay\'ın yörüngesi Güneş\'in çevresindedir', 'Tutulmalar yalnızca kış aylarında olur', 'Ay her ay farklı bir gezegenin gölgesinden geçerek kararır'], 'Ay çoğu zaman Güneş-Dünya doğrultusunun biraz üstünden ya da altından geçer. Tutulma için Ay\'ın Yeni Ay ya da Dolunay sırasında yörünge düğümlerinden birine yakın olması gerekir.'),
  ('Tam Ay tutulması sırasında Ay çoğunlukla tümüyle kararmaz, bakır kırmızısı bir renk alır. Bunun nedeni nedir?', 'Dünya atmosferinin kırmızı ışığı kırarak gölgeye yöneltmesi', ['Ay yüzeyindeki demir oksitli tozun kendiliğinden parlaması', 'Güneş\'in kırmızı dev olması', 'Mars\'ın yansıttığı ışığın Ay\'a ulaşması'], 'Güneş ışığı Dünya atmosferinden geçerken mavi ışık saçılır, kırmızı ışık ise kırılarak gölge konisinin içine bükülür. Ay\'a ulaşan bu ışık, dünyadaki tüm gün doğumu ve batımlarının ışığına benzer.'),
  ('Halkalı Güneş tutulması neden oluşur?', 'Ay yeröte yakınında olduğundan görünür çapı Güneş diskini tamamen örtemez', ['Ay\'ın bir kısmı şeffaf olduğundan', 'Dünya\'nın gölgesi Güneş\'i halka biçiminde örttüğünden', 'Güneş\'in çevresinde gerçek bir halka bulunduğundan'], 'Ay Dünya\'dan uzaktayken görünür çapı Güneş\'inkinden biraz küçük kalır; bu durumda Ay\'ın çevresinde parlak bir Güneş halkası görülür.'),
  ('Tam Güneş tutulmasının yeryüzünde yalnızca dar bir şerit boyunca görülebilmesinin nedeni nedir?', 'Ay\'ın tam gölgesinin (umbra) Dünya yüzeyine küçük bir alan olarak düşmesi', ['Güneş ışığının yalnızca ekvatora ulaşması', 'Tutulmanın yalnızca bir dakika sürmesi', 'Bulutların öteki bölgeleri örtmesi'], 'Ay\'ın gölge konisinin ucu Dünya\'ya ancak birkaç yüz kilometrelik bir alan olarak ulaşır. Bu alan Dünya döndükçe ve Ay ilerledikçe bir şerit çizer; çevresindeki geniş bölgede yalnızca parçalı tutulma görülür.'),
  ('Gelgit genliğinin en büyük olduğu "kaba gelgitler" (sizigi) hangi Ay evrelerinde yaşanır?', 'Yeni Ay ve Dolunay', ['İlk dördün ve son dördün', 'Yalnızca ilk dördün', 'Yalnızca hilal evreleri'], 'Yeni Ay ve Dolunay\'da Güneş, Dünya ve Ay aynı doğru üzerindedir; iki gelgit etkisi birbirine eklenir ve kabarma ile alçalma arasındaki fark en büyük olur.'),
  ('Ay\'ın dördün evrelerinde gelgit genliği neden en küçük olur?', 'Güneş ve Ay\'ın gelgit etkileri birbirine dik açıyla etki ederek kısmen birbirini götürür', ['Ay bu evrelerde Dünya\'dan çok uzaklaştığı için', 'Güneş bu evrelerde gelgit oluşturmadığı için', 'Okyanuslar bu evrelerde donduğu için'], 'Dördün evrelerinde Güneş ve Ay, Dünya\'dan bakıldığında 90° açı yapar. Güneş\'in yarattığı şişkinlik Ay\'ınkinin çukur bölgelerine düşer ve "ölü gelgitler" oluşur.'),
  ('Mars\'ın ekvator bölgesi boyunca uzanan ve binlerce kilometre uzunluğundaki dev kanyon sistemine ne ad verilir?', 'Valles Marineris', ['Mare Imbrium', 'Olympus Mons', 'Hellas Planitia çarpma havzası'], 'Valles Marineris yaklaşık 4 000 km uzunluğunda ve yer yer 7 km derinliğindedir; Dünya\'daki Büyük Kanyon\'dan çok daha büyüktür.'),
  ('Mars\'ın kutuplarında görülen ve mevsimlere göre büyüyüp küçülen beyaz örtüler neyden oluşur?', 'Su buzu ve donmuş karbondioksit', ['Tuz kristalleri', 'Beyaz kum ve kireçtaşı', 'Sıvı azot ve helyum gölleri ile tuz kristalleri'], 'Mars\'ın kutup başlıkları su buzu içerir; kışın üzerlerine atmosferden donan karbondioksit (kuru buz) eklenir, yazın bu katman süblimleşir.'),
  ('Mars\'ın eksen eğikliği Dünya\'nınkine oldukça yakındır (yaklaşık 25°). Bu benzerliğin Mars için anlamı nedir?', 'Mars\'ta da mevsimler yaşanır', ['Mars\'ta gece ve gündüz yaşanmaz', 'Mars\'ın Güneş çevresindeki yılı Dünya\'nınkiyle eşittir', 'Mars\'ın kutuplarında her zaman yaz yaşanır'], 'Eksen eğikliği mevsimleri doğurur; Mars\'ın eğikliği Dünya\'nınkine benzediği için mevsimleri vardır, ancak yılı daha uzun olduğundan her mevsim yaklaşık iki kat uzun sürer.'),
  ('Mars\'ta bir gün (sol) yaklaşık ne kadar sürer?', 'Yaklaşık 24 saat 40 dakika', ['Yaklaşık 10 saat 40 dakika', '58 Dünya günü', '243 Dünya günü'], 'Mars\'ın kendi ekseni çevresindeki dönüşü Dünya\'nınkine çok yakındır; bir Mars güneş günü yaklaşık 24 saat 39 dakika, yıldız günü ise yaklaşık 24 saat 37 dakikadır.'),
  ('Mars yüzeyinde kurumuş nehir yatakları, delta yapıları ve suyla oluşan mineraller bulunması neyi düşündürür?', 'Geçmişte Mars\'ta sıvı suyun aktığını', ['Mars\'ın eskiden Güneş\'e daha uzak olduğunu', 'Mars\'ta bugün okyanuslar bulunduğunu', 'Bu yapıların rüzgârla oluşamayacağı için Mars\'ta hiç atmosfer olmadığını'], 'Bu jeolojik izler, Mars\'ın milyarlarca yıl önce daha kalın bir atmosfere ve yüzeyde akan suya sahip olduğunu gösterir.'),
  ('Mars ile Dünya arasındaki uzaklık zamanla çok değişir. Mars\'ın Dünya\'dan en parlak ve en büyük göründüğü konuma ne ad verilir?', 'Karşı konum (Güneş\'in tam karşısında olma)', ['Kavuşum (Güneş ile aynı doğrultuda olma)', 'En büyük uzanım', 'Yerberi geçişi ya da en büyük uzanım'], 'Bir dış gezegen karşı konumdayken Dünya, Güneş ile o gezegenin arasındadır; uzaklık en aza iner ve gezegen bütün gece görülür.'),
  ('Mars\'ın yüzey çekim ivmesi Dünya\'nınkinin yaklaşık %38\'idir. Dünya\'da 1 m yükseğe zıplayabilen biri, aynı hızla Mars\'ta yaklaşık ne kadar yükseğe zıplar?', 'Yaklaşık 2,6 m', ['Yaklaşık 0,4 m', 'Yaklaşık 0,38 m', 'Yaklaşık 6 m'], 'Aynı başlangıç hızında ulaşılan yükseklik h = v²/2g ile hesaplanır ve g ile ters orantılıdır: 1 / 0,38 ≈ 2,6 m.'),
  ('Kızıl Gezegen\'de geçen bir yıl, kabaca kaç Dünya yılına karşılık gelir?', '1,9', ['0,6', '3,2', '11,9'], 'Mars Dünya\'dan daha uzakta ve daha yavaş dolandığından bir Mars yılı yaklaşık 687 Dünya günü sürer; 687 / 365 ≈ 1,9 eder.'),
  ('NASA\'nın 2012\'de Gale Krateri\'ne indirdiği ve araba boyutundaki keşif aracının adı nedir?', 'Curiosity', ['Sojourner', 'Spirit', 'Viking 1'], 'Curiosity, Mars Bilim Laboratuvarı görevinin keşif aracıdır; Gale Krateri\'nde eski göl ortamlarının izlerini incelemiştir.'),
  ('2021\'de Mars\'a inen Perseverance keşif aracının taşıdığı Ingenuity aracını tarihî kılan özellik neydi?', 'Başka bir gezegende güç kullanarak kontrollü uçuş yapan ilk araç olması', ['Mars\'a ulaşan ilk insan yapımı cisim olması', 'Mars\'tan Dünya\'ya geri dönen ilk araç olması', 'Mars\'ta hiç Güneş paneli kullanmadan çalışan ilk denizaltı olması'], 'Ingenuity, ince Mars atmosferinde uçmak için çok hızlı dönen pervaneler kullanan küçük bir helikopterdir ve 2021\'de ilk kontrollü uçuşunu gerçekleştirmiştir.'),
  ('Mars ile Dünya arasındaki uzaklık nedeniyle Mars\'taki bir keşif aracının Dünya\'dan joystick ile anlık sürülmesi neden mümkün değildir?', 'Radyo sinyallerinin gidiş-dönüşü dakikalar sürer', ['Radyo dalgaları Mars atmosferini hiç geçemez', 'Mars\'ın manyetik alanı tüm sinyalleri yansıtır', 'Keşif araçları yalnızca gece çalışır ve gündüz uyku kipine geçer'], 'Uzaklığa göre bir radyo sinyali Mars\'a tek yönde yaklaşık 3 ile 22 dakikada ulaşır. Bu gecikme yüzünden araçlar komut dizileriyle ve kısmen kendi kendilerine sürülür.'),
  ('Jüpiter\'in bir günü (kendi ekseni çevresinde dönüşü) yaklaşık 10 saattir. Bu hızlı dönüşün gezegenin biçimine etkisi nedir?', 'Kutuplardan basık, ekvatordan şişkin bir biçim alması', ['Tam bir küre biçiminde kalması', 'Kutuplardan sivrilerek yumurta biçimine girmesi', 'Ekvatordan içe doğru çökerek kum saati biçimini alması'], 'Hızlı dönme, ekvatorda maddeyi dışa doğru savurur; bu yüzden Jüpiter\'in ekvator çapı kutup çapından belirgin biçimde büyüktür.'),
  ('Io, Güneş sistemindeki volkanik açıdan en etkin cisimdir. Bu yoğun volkanizmanın enerji kaynağı nedir?', 'Jüpiter\'in güçlü gelgit kuvvetlerinin Io\'nun içini esnetip ısıtması', ['Io\'nun çekirdeğindeki uranyumun bölünmesi', 'Güneş ışığının yüzeyi eritmesi', 'Sürekli düşen göktaşlarının çarpma enerjisinin kabuğu ve mantoyu tümüyle eritmesi'], 'Io\'nun yörüngesi komşu uyduların etkisiyle tam çember olamaz; Jüpiter\'e yaklaşıp uzaklaştıkça gelgit şişkinliği değişir. Bu sürekli esneme sürtünmeyle ısı üretir.'),
  ('Europa\'nın, Güneş sisteminde yaşam aranacak en umut verici yerlerden biri sayılmasının nedeni nedir?', 'Buz kabuğunun altında sıvı su okyanusu bulunduğunun düşünülmesi', ['Yüzeyinde ormanlar gözlenmiş olması', 'Atmosferinin Dünya\'nınkiyle aynı olması', 'Yüzey sıcaklığının yıl boyu yaklaşık 20 °C civarında seyretmesi ve okyanuslarının buz tutmaması'], 'Europa\'nın kırık buz yüzeyi ve manyetik alan ölçümleri, kabuğun altında tuzlu bir okyanus bulunduğunu gösterir. Sıvı su, bildiğimiz yaşam için temel koşullardan biridir.'),
  ('Callisto\'nun yüzeyi Güneş sistemindeki en yoğun kraterlerle kaplı yüzeylerden biridir. Bu durum Callisto hakkında ne düşündürür?', 'Yüzeyi çok eski ve jeolojik olarak durgundur', ['Yüzeyi sürekli lavla yenilenmektedir', 'Callisto çok genç bir uydudur', 'Kraterler tümüyle rüzgâr aşındırmasıyla oluşmuştur'], 'Bir yüzeyde ne kadar çok krater varsa o yüzey o kadar uzun süredir değişmeden duruyor demektir. Io\'nun tersine Callisto\'da yüzeyi yenileyen etkin süreçler yoktur.'),
  ('1994\'te parçalara ayrılmış bir kuyruklu yıldızın Jüpiter\'e çarpması gözlendi. Bu kuyruklu yıldızın adı nedir?', 'Shoemaker-Levy 9', ['Halley', 'Hale-Bopp Kuyruklu Yıldızı', 'Swift-Tuttle'], 'Jüpiter\'in gelgit kuvvetiyle parçalanan Shoemaker-Levy 9\'un parçaları Temmuz 1994\'te art arda gezegene çarptı; bu, iki Güneş sistemi cisminin çarpışmasının ilk doğrudan gözlemiydi.'),
  ('Jüpiter\'i küçük bir teleskopla gözleyen biri, birkaç gece arka arkaya gezegenin yanında yer değiştiren dört parlak nokta görüyor. Bu noktalar neden bazen üç ya da ikiye iner?', 'Bazı uydular Jüpiter\'in önünden ya da arkasından geçer', ['Uydular zaman zaman söner ve yeniden yanar', 'Jüpiter\'in halkaları onları kalıcı olarak yutar', 'Dünya atmosferindeki bulutlar onları her gece farklı biçimde gizler'], 'Uydular Jüpiter\'in çevresinde dolandıkça gezegenin diskinin önüne geçebilir, arkasına saklanabilir ya da Jüpiter\'in gölgesine girerek tutulabilir.'),
  ('Satürn\'ün ortalama yoğunluğu suyunkinden düşüktür. Bu bilgiden hangi sonuç çıkarılabilir?', 'Gezegen büyük ölçüde hafif gazlardan oluşur', ['Gezegenin içi tamamen boştur', 'Satürn suya atılsa batar', 'Gezegen kayaç ve demirden oluşan sert bir kabuğa sahiptir'], 'Satürn\'ün ortalama yoğunluğu yaklaşık 0,69 g/cm³\'tür. Bu, onun çoğunlukla hidrojen ve helyumdan oluştuğunu gösterir; ortalama yoğunluğu sudan düşük olan tek gezegendir.'),
  ('Satürn\'ün halkalarındaki en belirgin boşluk olan ve iki ana halkayı ayıran aralığın adı nedir?', 'Cassini Bölümü', ['Kuiper Boşluğu', 'Encke Çizgisi ve Roche Bölgesi', 'Kirkwood Kuşağı'], 'Cassini Bölümü, A ve B halkalarını ayıran yaklaşık 4 800 km genişliğindeki karanlık aralıktır; küçük teleskoplarla bile görülebilir.'),
  ('Satürn\'ün kuzey kutbunda gözlenen ve altı kenarlı bir biçimi olan bulut yapısına ne ad verilir?', 'Altıgen (hekzagon) fırtına', ['Büyük Kırmızı Leke', 'Büyük Kara Leke benzeri bir girdap', 'Kuzey Işığı Halkası'], 'Satürn\'ün kuzey kutbundaki altıgen, kutup çevresinde dönen jet akımlarının oluşturduğu kararlı bir dalga yapısıdır; Voyager ve Cassini tarafından incelenmiştir.'),
  ('Halkaları olan dev gezegenler için aşağıdaki ifadelerden hangisi doğrudur?', 'Dört dev gezegenin her birinde halka sistemi bulunur', ['Yalnızca Satürn\'ün halkası vardır', 'Yalnızca Satürn ve Jüpiter\'in halkası vardır', 'Halkalar yalnızca Dünya\'ya benzeyen kaya gezegenlerinde bulunur'], 'Dört dev gezegenin her birinin halkası vardır; ancak Satürn\'ünkiler en parlak ve en büyük olanlardır. Diğerlerinin halkaları sönük olduğu için uzay araçları ve özel gözlemlerle keşfedilmiştir.'),
  ('Satürn Güneş çevresindeki turunu yaklaşık kaç yılda tamamlar?', '29,5', ['11,9', '84', 'Yaklaşık 165'], 'Satürn\'ün yörünge dönemi yaklaşık 29,5 Dünya yılıdır; Jüpiter\'inki 11,9, Uranüs\'ünkü 84, Neptün\'ünkü 165 yıldır.'),
  ('Titan\'ın yüzeyinde göller ve denizler bulunur. Bu göllerde hangi sıvılar vardır?', 'Metan ve etan', ['Su ve tuz', 'Sıvı demir', 'Sülfürik asit ve erimiş kükürt karışımı'], 'Titan\'da sıcaklık yaklaşık −180 °C\'dir; bu koşullarda metan ve etan sıvı hâlde bulunur ve Dünya\'daki su döngüsüne benzer bir döngü oluşturur.'),
  ('Satürn\'ün uydusu Enceladus\'un güney kutbundan uzaya fışkıran su buharı ve buz parçacıkları neyin kanıtı sayılır?', 'Buz kabuğunun altında sıvı su okyanusu bulunduğunun', ['Uydunun yüzeyinde sıcak lav gölleri olduğunun', 'Satürn\'ün halkalarının Enceladus\'tan kaçtığının', 'Uydunun yakında tamamen buharlaşıp ortadan kalkacağının'], 'Cassini uzay aracı bu fışkırmalardan geçerek tuz, silika ve organik moleküller saptadı; bu bulgular kabuğun altında ısınan bir okyanusu işaret eder.'),
  ('Uranüs ve Neptün\'ün mavi-yeşil renkte görünmesinin nedeni nedir?', 'Atmosferdeki metanın kırmızı ışığı soğurması', ['Yüzeylerinin okyanuslarla kaplı olması', 'Yüzeylerini örten mavi renkli dev buzulların güneş ışığını yansıtması', 'Güneş\'ten yalnızca mavi ışık alabilmeleri'], 'Metan gazı kırmızı ışığı soğurur, mavi ve yeşil ışığı ise saçar. Bu yüzden atmosferinde metan bulunan bu iki gezegen mavimsi görünür.'),
  ('Uranüs, teleskopla keşfedilen ilk gezegendir. Kim tarafından ve ne zaman keşfedilmiştir?', 'William Herschel, 1781', ['Galileo Galilei, 1610 yılında', 'Johannes Kepler, 1609', 'Clyde Tombaugh, 1930'], 'William Herschel, 1781\'de teleskopla gökyüzünü tararken Uranüs\'ü fark etti; başta onu bir kuyruklu yıldız sandı.'),
  ('Neptün\'ün keşfini bilim tarihinde özel kılan şey nedir?', 'Konumunun önce Uranüs\'ün yörüngesindeki sapmalardan hesaplanması', ['Çıplak gözle bulunan son gezegen olması', 'Bir uzay aracı tarafından keşfedilmesi', 'Uydusundan önce halkasının fark edilmesi'], 'Uranüs\'ün beklenen yoldan sapması başka bir gezegenin çekimine bağlandı. Le Verrier\'in hesapladığı konumda Neptün 1846\'da Galle tarafından gözlendi.'),
  ('Neptün\'ün en büyük uydusu Triton\'u sıra dışı kılan yörünge özelliği nedir?', 'Gezegenin dönüş yönünün tersine dolanması', ['Neptün\'e hiç yaklaşmadan sabit durması', 'Güneş\'in çevresinde dolanması', 'Neptün\'ün halkalarının içinden geçerek her turda yön değiştirmesi'], 'Triton, büyük uydular arasında geri yönde (retrograd) dolanan tek uydudur. Bu durum onun Kuiper kuşağından yakalanmış bir cisim olduğunu düşündürür.'),
  ('Uranüs ve Neptün\'ü yakından inceleyen tek uzay aracı hangisidir?', 'Voyager 2', ['Voyager 1', 'Pioneer 10', 'Cassini'], 'Voyager 2, 1986\'da Uranüs\'ün, 1989\'da Neptün\'ün yakınından geçti; bu iki gezegene ait yakın görüntülerin çoğu bu araçtan gelmektedir.'),
  ('Neptün çıplak gözle görülebilir mi?', 'Hayır, en az bir dürbün ya da teleskop gerekir', ['Evet, en parlak yıldızlar kadar parlaktır', 'Evet, yalnızca kutup bölgelerinden', 'Yalnızca Ay tutulması sırasında, Ay ışığı azalınca görülebilir'], 'Neptün\'ün parlaklığı yaklaşık 7,8 kadirdir; çıplak gözle görülebilecek sınırın (yaklaşık 6 kadir) altındadır.'),
  ('Plüton dışında Kuiper kuşağı ya da ötesinde yer alan cüce gezegenlerden biri aşağıdakilerden hangisidir?', 'Eris', ['Ceres', 'Vesta', 'Ganymede'], 'Eris, Plüton ile benzer büyüklükte bir cüce gezegendir ve keşfi gezegen tanımının yeniden ele alınmasında etkili olmuştur. Ceres asteroit kuşağındadır, Vesta ise bir asteroittir.'),
  ('Asteroit kuşağındaki maddenin neden tek bir gezegen olarak birleşemediği düşünülür?', 'Jüpiter\'in kütle çekimi cisimlerin yörüngelerini bozup çarpışmaları parçalayıcı yaptı', ['Bu bölgede kütle çekimi işlemez', 'Asteroitler birbirini manyetik olarak iter', 'Güneş rüzgârı burada birleşmeyi engelleyen bir duvar oluşturur ve tüm tozu Jüpiter\'e taşır'], 'Jüpiter\'in güçlü çekimi kuşaktaki cisimleri hızlandırdı; çarpışmalar birleşme yerine parçalanmayla sonuçlandı ve maddenin çoğu kuşaktan dışarı atıldı.'),
  ('Bilim kurgu filmlerinde asteroit kuşağı genellikle uzay araçlarının çarpmamak için zor manevralar yaptığı sık bir kaya yığını olarak gösterilir. Bu tasvir neden gerçeği yansıtmaz?', 'Asteroitler arasında çoğunlukla milyonlarca kilometre boşluk vardır', ['Asteroitler gerçekte hep birbirine değer', 'Kuşakta yalnızca toz vardır, kaya yoktur', 'Asteroitler gerçekte çok daha büyük ve sıktır, tasvir onları olduğundan seyrek gösterir'], 'Kuşaktaki toplam kütle Ay\'ınkinin yalnızca birkaç yüzdesi kadardır ve çok geniş bir hacme dağılmıştır. Bugüne dek oradan geçen uzay araçlarının hiçbiri asteroitlerden kaçınmak için manevra yapmak zorunda kalmamıştır.'),
  ('NASA\'nın DART görevi 2022\'de Dimorphos adlı küçük asteroide bilerek bir araç çarptırdı. Bu deneyin asıl amacı neydi?', 'Bir asteroidin yörüngesini çarpma ile değiştirebilmeyi sınamak', ['Asteroitten maden çıkarmak', 'Asteroidi tamamen yok etmek', 'Asteroidi Dünya\'nın çevresinde dolanacak yeni bir uydu hâline getirmek'], 'DART, Dünya\'yı tehdit edebilecek bir asteroidin rotasını saptırma yönteminin ilk gerçek denemesiydi. Çarpma sonrası Dimorphos\'un Didymos çevresindeki dolanım süresi ölçülebilir biçimde kısaldı.'),
  ('Göktaşlarının çoğunun asteroitlerden koptuğu biliniyor. Bu, göktaşlarını bilim açısından değerli kılan hangi özelliği açıklar?', 'Güneş sisteminin oluşumundan kalma, değişmemiş madde taşıyabilmeleri', ['Dünya\'daki kayaçlardan daha genç olmaları', 'İçlerinde her zaman fosil bulunması', 'Dünya\'ya ulaştıklarında sıvı hâlde olmaları ve içlerinde canlı hücre taşımaları'], 'Asteroitler gezegen oluşumundan artakalan yapı taşlarıdır. Özellikle kondrit türü göktaşları 4,6 milyar yıl öncesinin maddesini neredeyse değişmeden korur.'),
  ('Kuyruklu yıldızların çoğunda iki ayrı kuyruk görülür. Bunlar hangileridir?', 'Mavimsi iyon kuyruğu ve sarımsı toz kuyruğu', ['Kırmızı demir kuyruğu ve yeşil buz kuyruğu', 'Ön kuyruk ve arka kuyruk', 'Sıcak kuyruk ile soğuk kuyruk, ikisi de aynı yönde'], 'İyon kuyruğu güneş rüzgârıyla Güneş\'in tam tersi yönde düz uzanır ve iyonlaşmış gazlar yüzünden mavimsidir. Toz kuyruğu güneş ışığını yansıtır, daha kavislidir.'),
  ('Avrupa Uzay Ajansı\'nın Rosetta görevini tarihe geçiren olay nedir?', 'Bir kuyruklu yıldızın yörüngesine girip yüzeyine iniş aracı göndermesi', ['Bir asteroidi Dünya\'ya getirmesi', 'Güneş\'in yüzeyine inmesi', 'Plüton\'un uydusu Charon\'a ilk kez sondaj makinesi ile delik açması'], 'Rosetta, 67P/Churyumov-Gerasimenko kuyruklu yıldızının yörüngesine girdi ve 2014\'te Philae adlı iniş aracını yüzeyine indirdi; bu bir ilkti.'),
  ('Bir kuyruklu yıldız Güneş\'e her yaklaşışında bir miktar buz ve toz kaybeder. Bunun uzun vadeli sonucu ne olabilir?', 'Uçucu maddelerini tüketip etkinliğini yitirmesi ya da dağılması', ['Her geçişte daha da büyüyüp sonunda bir gezegene dönüşmesi', 'Yörüngesinin Güneş\'ten tamamen bağımsız hâle gelmesi', 'Kütlesi artarak sonunda yeni bir yıldıza dönüşmesi'], 'Sürekli madde kaybı kuyruklu yıldızı zamanla tüketir; geride sönmüş, asteroide benzeyen bir çekirdek ya da yörüngesine saçılmış bir toz akımı kalabilir.'),
  ('Meteor, meteoroit ve göktaşı (meteorit) terimleri için aşağıdakilerden hangisi doğrudur?', 'Atmosfere girip ışık saçan cisme meteor, yere ulaşan parçaya göktaşı denir', ['Göktaşı uzaydaki her kayadır, meteor ise yalnızca demirden oluşanıdır', 'Meteor uzaydaki kaya parçasıdır, meteoroit ise yere düşmüş taştır', 'Üç terim aynı şeyi anlatır ve aralarında anlam farkı yoktur'], 'Uzayda dolanan küçük kaya ya da metal parçası meteoroittir. Atmosferde yanarken oluşturduğu ışık izi meteor (halk arasında "yıldız kayması"), yere ulaşan kalıntısı ise göktaşıdır.'),
  ('Atmosfere giren küçük bir meteoroidi parlatan asıl etken nedir?', 'Çok yüksek hızla sıkıştırdığı havanın onu ve çevresini ısıtması', ['Güneş ışığını yansıtması', 'Kendi içindeki radyoaktif maddeler', 'Dünya\'nın manyetik alanının onu bir elektrik akımıyla tutuşturması'], 'Meteoroitler saniyede onlarca kilometre hızla atmosfere girer. Önlerindeki hava sıkışarak çok ısınır; cisim buharlaşır ve çevresindeki gaz parlar.'),
  ('Yeryüzünde bulunan göktaşları bileşimlerine göre başlıca hangi üç gruba ayrılır?', 'Taş, demir ve taş-demir göktaşları', ['Buz, gaz ve toz göktaşları', 'Kırmızı, mavi ve yeşil göktaşları', 'Volkanik, tortul ve başkalaşım göktaşları'], 'Göktaşlarının çoğu taş göktaşıdır; demir göktaşları ise demir-nikel alaşımından oluşur. Taş-demir göktaşları her ikisini de içerir.'),
  ('Güneş sistemini çok uzaklardan küre biçiminde sardığı varsayılan ve uzun dönemli kuyruklu yıldızların kaynağı olduğu düşünülen bölge hangisidir?', 'Oort bulutu', ['Kuiper kuşağı', 'Asteroit kuşağı', 'Heliosferin Güneş rüzgârının durduğu sınırı olan heliopoz'], 'Oort bulutu Güneş\'ten binlerce, belki 100 000 AB\'ye kadar uzanan kuramsal bir buzlu cisimler topluluğudur. Henüz doğrudan gözlenmemiştir; varlığı kuyruklu yıldız yörüngelerinden çıkarılır.'),
  ('Kuiper kuşağı ile asteroit kuşağının cisimleri arasındaki temel bileşim farkı nedir?', 'Kuiper kuşağı cisimleri buzca zengin, asteroitler ise çoğunlukla kayaç ve metaldir', ['Kuiper kuşağı cisimleri yalnızca demirden oluşur', 'Asteroitler buz, Kuiper kuşağı cisimleri gazdır', 'İki kuşakta da cisimler tamamen aynı bileşimdedir ve yalnızca uzaklıkları farklıdır'], 'Asteroit kuşağı kar çizgisinin yakınında, sıcak bölgede kaldığından cisimleri daha kayalıktır. Güneş\'ten çok uzaktaki Kuiper kuşağında ise su, metan ve azot buzları korunmuştur.'),
  ('Güneş rüzgârının yıldızlar arası ortamın basıncıyla dengelenerek durduğu sınıra ne ad verilir?', 'Heliopoz', ['Kuiper sınırı', 'Roche sınırı', 'Olay ufku'], 'Heliopoz, Güneş\'in etki alanı sayılan heliosferin dış sınırıdır. Voyager 1 bu sınırı 2012\'de, Voyager 2 ise 2018\'de geçti.'),
  ('Dünya yörüngesinde en hızlı hareket ettiği dönemi yılın hangi zamanında yaşar?', 'Ocak ayı başlarında', ['Temmuz ayı başlarında', 'Mart ekinoksunda', 'Eylül ekinoksunda'], 'Dünya günberiye ocak başında ulaşır. Kepler\'in ikinci yasası gereği Güneş\'e en yakın olduğu bu dönemde yörünge hızı en yüksektir.'),
  ('Kepler\'in üçüncü yasasına göre, Güneş çevresinde dolanan bir cismin yörünge dönemi T (yıl) ile ortalama uzaklığı a (AB) arasındaki ilişki hangisidir?', 'T² = a³', ['T = a', 'T³ = a²', 'T = a²'], 'Güneş çevresindeki yörüngelerde dönemin karesi, yarı büyük eksenin küpüyle orantılıdır. Yıl ve AB birimleri kullanıldığında orantı sabiti 1 olur.'),
  ('Güneş\'ten ortalama 4 AB uzaklıkta dolanan bir asteroidin yörünge dönemi kaç yıldır?', '8', ['4', '16', '64'], 'T² = a³ = 4³ = 64 olduğundan T = 8 yıl bulunur.'),
  ('Bir yörüngenin ne kadar basık (yassı) olduğunu gösteren sayıya ne ad verilir?', 'Dışmerkezlik', ['Eğiklik', 'Presesyon', 'Yarı küçük eksenin yörüngeye dik doğrultudaki açısı'], 'Dışmerkezlik (eksantrisite) 0 ise yörünge tam çemberdir; 0 ile 1 arasında değerler elipsleri gösterir. Gezegenlerin çoğunun dışmerkezliği küçüktür.'),
  ('Uluslararası Uzay İstasyonu\'ndaki astronotlar ağırlıksız gibi yüzer. Bunun gerçek nedeni nedir?', 'İstasyon ve astronotlar birlikte sürekli serbest düşüştedir', ['O yükseklikte kütle çekimi sıfırdır', 'İstasyon Dünya\'nın atmosferinin dışında olduğu için çekim ortadan kalkar', 'Astronotların kütlesi uzayda sıfıra iner'], 'Yaklaşık 400 km yükseklikte çekim ivmesi yerdekinin yaklaşık %90\'ıdır. İstasyon ve içindekiler aynı ivmeyle düşer, ancak yanal hızları yüzünden Dünya\'yı ıskalayarak çevresinde dolanır.'),
  ('Ay\'ın neredeyse hiç atmosferi olmamasının nedenlerinden biri hangisidir?', 'Kaçış hızının düşük olması gaz moleküllerinin uzaya kaçmasını kolaylaştırır', ['Ay\'ın çok soğuk olması gazların oluşmasını tamamen engeller', 'Dünya, Ay\'ın tüm gazını kendine çeker', 'Ay\'da hiçbir zaman gaz bulunmamıştır, çünkü Ay tümüyle demirden oluşmuştur'], 'Ay\'ın kaçış hızı yaklaşık 2,4 km/s\'dir. Güneş\'le ısınan gaz moleküllerinin bir kısmı bu hıza kolayca ulaşır ve zamanla uzaya kaçar.'),
  ('Yer durağan (jeostatik) uydular ekvator üzerinde yaklaşık 36 000 km yükseklikte dolanır. Bu yüksekliğin özelliği nedir?', 'Bu yükseklikte dolanma süresi Dünya\'nın dönüş süresine eşittir', ['Bu yükseklikte kütle çekimi tamamen ortadan kalkar', 'Bu yükseklikte atmosfer en yoğundur', 'Bu yükseklik Ay\'ın Dünya\'ya en yakın olduğu uzaklıktır'], 'Yaklaşık 35 786 km yükseklikteki dairesel yörüngede dönem bir yıldız gününe (yaklaşık 23 saat 56 dakika) eşittir; bu yüzden uydu yerden bakan için gökyüzünde sabit durur.'),
  ('Bir uydu, Dünya\'ya daha yakın bir dairesel yörüngeye indirilirse yörünge hızı ve dolanma süresi nasıl değişir?', 'Hızı artar, dolanma süresi kısalır', ['Hızı azalır, dolanma süresi uzar', 'Hızı artar, dolanma süresi uzar', 'İkisi de değişmez, çünkü yalnızca uydunun kütlesine bağlıdır'], 'Dairesel yörünge hızı v = √(GM/r) ile verilir; r küçülünce hız artar. Hem yol kısaldığı hem hız arttığı için dönem de kısalır.'),
  ('Güneş ile bir gezegenin çekimlerinin, küçük bir cismin onlarla birlikte sabit bir düzende dolanmasına izin verdiği beş özel noktaya ne ad verilir?', 'Lagrange noktaları', ['Kirkwood noktaları', 'Ekinoks noktaları', 'Düğüm noktaları ve yörüngelerin kesiştiği yeri gösteren apsit noktaları'], 'Lagrange noktalarında iki büyük cismin çekimleri ve dönen sistemdeki merkezkaç etkisi dengelenir. James Webb Uzay Teleskobu Güneş-Dünya sisteminin L2 noktası çevresinde dolanır.'),
  ('Bir gezegenin ya da uydunun kendi ekseni çevresindeki dönüş süresinin yörünge dönemine eşitlenmesine ne ad verilir?', 'Gelgit kilitlenmesi', ['Yörünge rezonansı ve presesyon', 'Geri devinim', 'Presesyon'], 'Gelgit sürtünmesi, bir uydunun dönüşünü zamanla yörünge dönemine eşitler; Ay\'ın Dünya\'ya hep aynı yüzünü göstermesi buna örnektir.'),
  ('Uzay araçlarının Jüpiter gibi büyük bir gezegenin yakınından geçerek yakıt harcamadan hız kazanmasına ne ad verilir?', 'Kütle çekimi yardımı', ['Aerofren', 'Işık yelkeni', 'Hohmann geçiş yörüngesi ile frenleme'], 'Gezegenin yakınından uygun açıyla geçen araç, gezegenin Güneş çevresindeki hareketinden bir miktar momentum alır. Voyager ve Cassini bu yöntemi defalarca kullandı.'),
  ('Bir öğrenci "Güneş Dünya\'yı çektiği kadar Dünya da Güneş\'i çeker" diyor. Bu ifade fizik açısından nasıl değerlendirilir?', 'Doğrudur; Newton\'un üçüncü yasasına göre kuvvetler eşit büyüklüktedir', ['Yanlıştır; Güneş çok büyük olduğu için daha büyük kuvvet uygular', 'Yanlıştır; Dünya Güneş\'i hiç çekmez', 'Doğrudur; ama bu yüzden Güneş de Dünya ile aynı ivmeyle hareket eder ve aynı yörüngeyi izler'], 'Etki ve tepki kuvvetleri eşit büyüklükte ve zıt yönlüdür. Ancak Güneş\'in kütlesi çok büyük olduğu için aynı kuvvetin ona kazandırdığı ivme çok küçüktür.'),
  ('Kuyruklu yıldızların yörüngeleri çoğu zaman çok basık elipslerdir. Kepler\'in ikinci yasası bu cisimler için hangi sonucu doğurur?', 'Güneş\'e yakınken çok hızlı geçer, uzak bölgelerde yıllarca yavaş ilerlerler', ['Yörüngelerinin her yerinde aynı hızla hareket ederler', 'Güneş\'e yakınken dururlar', 'Güneş\'ten uzaklaştıkça hızlanırlar ve sonunda ışık hızına yaklaşırlar'], 'Eşit alanlar yasası, basık yörüngelerde hız farkını çok belirgin kılar. Bu yüzden kuyruklu yıldızlar dönemlerinin küçük bir bölümünü Güneş\'in yakınında geçirir.'),
  ('Gök ekvatoru ile ekliptik arasındaki açı neden yaklaşık 23,5°\'dir?', 'Dünya\'nın dönme ekseninin yörünge düzlemine göre eğikliğinden', ['Güneş\'in kendi ekseninin eğikliğinden', 'Ay\'ın yörünge eğikliğinden', 'Samanyolu düzleminin Güneş sistemine göre konumundan'], 'Gök ekvatoru, Dünya ekvatorunun gökyüzüne izdüşümüdür; ekliptik ise yörünge düzlemini gösterir. Bu iki düzlem arasındaki açı doğrudan Dünya\'nın eksen eğikliğine eşittir.'),
  ('Gök cisimlerinin gök küresindeki konumunu belirtmek için kullanılan, coğrafi enlem ve boylama benzeyen koordinatlar hangileridir?', 'Dik açıklık ve sapma', ['Yükseklik ve uzaklık', 'Kırmızıya kayma ve parlaklık', 'Parsek ve ışık yılı'], 'Ekvatoral koordinat sisteminde sapma (deklinasyon) enleme, dik açıklık (sağ açıklık) boylama karşılık gelir; bu koordinatlar gözlem yerinden bağımsızdır.'),
  ('Bir yıldızın ufuktan yüksekliği ve yönü (azimutu) neden bir yıldız kataloğunda sabit değerler olarak verilemez?', 'Bu değerler gözlem yerine ve zamanına göre sürekli değişir', ['Yıldızlar hızla yer değiştirdiği için', 'Yükseklik yalnızca gezegenler için tanımlıdır', 'Azimut yalnızca Güneş için kullanılan, yıldızlara uygulanamayan bir ölçüdür'], 'Ufuk koordinatları gözlemcinin konumuna bağlıdır ve Dünya döndükçe değişir. Kataloglarda bu yüzden Dünya\'nın dönüşüyle değişmeyen ekvatoral koordinatlar kullanılır.'),
  ('Bir gözlemci gökyüzünde Kutup Yıldızı\'nı ufuktan yaklaşık 40° yükseklikte görüyor. Gözlemcinin bulunduğu yerin enlemi yaklaşık kaçtır?', '40° Kuzey', ['50° Kuzey', '40° Güney', '20° Kuzey'], 'Kuzey gök kutbunun ufuktan yüksekliği gözlemcinin enlemine eşittir. Kutup Yıldızı bu kutba çok yakın olduğundan yüksekliği enlemi verir.'),
  ('Kutup Yıldızı\'nı bulmak için genellikle Büyük Ayı takımyıldızının hangi bölümünden yararlanılır?', 'Kepçe biçimini oluşturan yedi yıldızın uç kısmındaki iki yıldızdan', ['Kepçenin sapındaki en uç yıldızdan', 'Orion\'un kemerindeki üç yıldızdan', 'Büyük Ayı\'nın en sönük yıldızından ve ona en yakın galaksiden'], 'Büyük Kepçe\'nin "ağzını" oluşturan iki yıldız (Dubhe ve Merak) arasındaki doğru yaklaşık beş kat uzatıldığında Kutup Yıldızı\'na ulaşılır.'),
  ('Ekvator üzerinde bulunan bir gözlemci Kutup Yıldızı\'nı nerede görür?', 'Kuzey ufkunun hemen üzerinde', ['Tam başucunda', 'Ufkun 45° üzerinde', 'Hiçbir zaman göremez ve onun yerine güneyde Güney Haçı\'nın tam başucunda olduğunu görür'], 'Enlem 0° olduğunda kuzey gök kutbunun yüksekliği de 0°\'dir; Kutup Yıldızı kuzey ufkuna çok yakın görünür.'),
  ('Bir takımyıldızı oluşturan yıldızlar için aşağıdakilerden hangisi genellikle doğrudur?', 'Dünya\'dan bakınca yan yana görünseler de uzaklıkları çok farklıdır', ['Tümü birbirine kütle çekimiyle bağlıdır', 'Tümü aynı bulutsudan aynı anda doğmuştur', 'Tümü Güneş\'e eşit uzaklıktadır'], 'Takımyıldızlar gökyüzündeki görünür desenlerdir. Bir takımyıldızdaki yıldızların biri birkaç ışık yılı, öbürü yüzlerce ışık yılı uzakta olabilir.'),
  ('Orion takımyıldızında, kırmızımsı renkli dev bir yıldız olan Betelgeuse ile mavimsi beyaz parlak Rigel bulunur. Bu renk farkı en doğrudan neyi gösterir?', 'Rigel\'in yüzeyinin Betelgeuse\'unkinden daha sıcak olduğunu', ['Betelgeuse\'un Rigel\'den daha yakın olduğunu', 'Rigel\'in bir gezegen olduğunu', 'Betelgeuse\'un Dünya\'dan uzaklaştığı için ışığının kırmızıya kaydığını'], 'Yıldızların rengi yüzey sıcaklıklarına bağlıdır; mavi yıldızlar sıcak, kırmızı yıldızlar daha soğuktur.'),
  ('Güneş, Ay ve gezegenlerin gökyüzünde izlediği yol boyunca dizilmiş takımyıldızlar kuşağına ne ad verilir?', 'Zodyak', ['Samanyolu', 'Gök ekvatoru', 'Kutup çevresi kuşağı ve bunun güneyindeki kuşak'], 'Gezegenlerin yörüngeleri yaklaşık aynı düzlemde olduğundan hepsi ekliptiğin yakınında, zodyak takımyıldızlarının önünde görülür.'),
  ('Güney Yarım Küre\'den bakıldığında güney yönünü bulmak için sıkça kullanılan küçük ama belirgin takımyıldız hangisidir?', 'Güney Haçı', ['Büyük Ayı', 'Kraliçe', 'Küçük Ayı'], 'Güney gök kutbunun yakınında parlak bir yıldız yoktur. Güney Haçı\'nın uzun ekseni uzatılarak güney gök kutbunun yeri bulunur.'),
  ('Aşağıdaki yıllardan hangisi Gregoryen takvime göre artık yıl değildir?', '1900', ['2000', '2024', '1996'], '1900, 100\'e bölünür ama 400\'e bölünmez; bu nedenle artık yıl değildir. 2000 ise 400\'e bölündüğü için artık yıldır.'),
  ('Hicri takvim gibi Ay\'ın evrelerine dayanan takvimlerde bir yıl yaklaşık 354 gündür. Bu durumun sonucu nedir?', 'Aylar her yıl mevsimlere göre yaklaşık 11 gün kayar', ['Aylar mevsimlerle her zaman aynı kalır', 'Bir yıl Güneş yılından 30 gün uzundur', 'Her yıl iki kez aynı ay tekrarlanır'], 'Ay takviminin 12 ayı yaklaşık 12 × 29,5 = 354 gün eder. Güneş yılından yaklaşık 11 gün kısa olduğu için Ramazan gibi aylar her yıl daha erken bir mevsime kayar.'),
  ('Dünya\'nın en büyük optik teleskoplarının hepsinin mercekli değil aynalı olmasının başlıca nedeni nedir?', 'Büyük aynalar arkadan desteklenebilir, büyük mercekler kendi ağırlığıyla bükülür', ['Aynalar ışığı daha az toplar', 'Mercekler yalnızca kızılötesi ışık geçirir', 'Aynalı teleskoplar mercekli olanlardan her zaman daha kısa ve hafiftir, bu da tek nedendir'], 'Mercek yalnızca kenarlarından tutulabilir ve büyüdükçe sarkar; ayrıca renk sapmasına yol açar. Ayna ise tüm arka yüzünden desteklenebilir, hatta parçalı yapılabilir.'),
  ('Mercekli teleskoplarda parlak cisimlerin kenarında renkli halkalar görülmesine yol açan kusura ne ad verilir?', 'Renk sapması', ['Küresel sapma', 'Işık kirliliği', 'Atmosferik kırılma ve onun yarattığı yıldız titreşimi'], 'Mercek farklı dalga boylarını farklı miktarda kırar; bu yüzden tüm renkler aynı noktada odaklanmaz. Aynalarda yansıma dalga boyuna bağlı olmadığından bu sorun yoktur.'),
  ('Çapı 20 cm olan bir teleskop, çapı 10 cm olan bir teleskoba göre kaç kat fazla ışık toplar?', '4', ['2', '8', '16'], 'Toplanan ışık, açıklığın alanıyla, yani çapın karesiyle orantılıdır: (20/10)² = 4.'),
  ('Bir teleskobun birbirine çok yakın iki yıldızı ayrı ayrı gösterebilme yeteneğine ne ad verilir ve bu neye bağlıdır?', 'Ayırma gücü; açıklık çapı büyüdükçe artar', ['Büyütme; göz merceği küçüldükçe sınırsızca artar', 'Parlaklık; teleskobun uzunluğuna bağlıdır', 'Odak oranı; yalnızca göz merceğinin rengine bağlıdır'], 'Kırınım nedeniyle bir teleskobun ayırabileceği en küçük açı, dalga boyunun açıklık çapına oranıyla orantılıdır; büyük açıklık daha ince ayrıntı gösterir.'),
  ('Bir satıcı küçük bir teleskobu "600 kat büyütme" yazısıyla övüyor. Bu reklam neden yanıltıcı olabilir?', 'Küçük açıklık bu büyütmede bulanık ve sönük görüntü verir', ['600 kat büyütme yasal olarak yasaktır', 'Büyütme arttıkça teleskop daha çok ışık toplar', 'Teleskopların büyütmesi hiçbir koşulda 50\'yi geçemez'], 'Kullanışlı en yüksek büyütme kabaca açıklığın milimetre cinsinden çapının iki katıdır. Örneğin 60 mm\'lik teleskop için bu yaklaşık 120 kattır; daha fazlası yalnızca bulanıklığı büyütür.'),
  ('Radyo teleskoplarının optik teleskoplardan çok daha büyük çanaklara sahip olmasının başlıca nedeni nedir?', 'Radyo dalgalarının dalga boyu çok uzun olduğu için iyi ayırma gücüne büyük açıklık gerekir', ['Radyo dalgaları çok hızlı olduğu için', 'Radyo dalgaları yalnızca gündüz gelir', 'Radyo teleskopları çanaklarıyla ses dalgalarını da topladığı için'], 'Ayırma gücü dalga boyu / çap oranıyla belirlenir. Santimetre ya da metre dalga boylarında görünür ışıktaki ayrıntıya yaklaşmak için çok büyük çanaklar ya da çanak dizileri gerekir.'),
  ('Radyo gözlemlerinin optik gözlemlere göre üstünlüklerinden biri aşağıdakilerden hangisidir?', 'Bulutlu havada ve gündüz de yapılabilmesi', ['Hiçbir anten ya da çanak gerektirmemesi', 'Yalnızca Güneş\'i gözleyebilmesi', 'Görüntülerin her zaman renkli fotoğraf olarak doğrudan elde edilmesi'], 'Radyo dalgalarının çoğu bulutlardan geçer ve gökyüzünün gündüz parlaklığı radyo bölgesinde sorun yaratmaz; bu yüzden radyo teleskopları gece gündüz çalışabilir.'),
  ('Yıldız oluşum bölgelerindeki genç yıldızlar görünür ışıkta toz bulutlarının arkasında gizlenir. Bu yıldızları görmek için en uygun gözlem bölgesi hangisidir?', 'Kızılötesi', ['Morötesi', 'X ışını', 'Gama ışını'], 'Kızılötesi ışığın dalga boyu toz parçacıklarına göre uzun olduğundan tozdan daha az saçılır ve bulutların içini görmemizi sağlar.'),
  ('Hubble Uzay Teleskobu hangi yılda yörüngeye yerleştirilmiştir?', '1990', ['1969', '1981', '2003'], 'Hubble, 1990\'da uzay mekiği Discovery ile fırlatıldı. İlk görüntüleri aynadaki bir kusur yüzünden bulanıktı; 1993\'teki bakım göreviyle düzeltici optik eklendi.'),
  ('James Webb Uzay Teleskobu\'nun Hubble\'dan temel farklarından biri nedir?', 'Ağırlıklı olarak kızılötesinde gözlem yapması', ['Yalnızca radyo dalgalarıyla çalışması', 'Dünya\'nın alçak yörüngesinde dolanması', 'Aynasının çok daha küçük olması ve tek parçalı cam mercek kullanması'], 'JWST 6,5 m\'lik altın kaplı parçalı aynasıyla çoğunlukla kızılötesinde gözlem yapar ve Dünya\'dan yaklaşık 1,5 milyon km uzaktaki L2 noktası çevresinde bulunur.'),
  ('Chandra uzay gözlemevi hangi tür ışınımla gözlem yapmak üzere tasarlanmıştır?', 'X ışını', ['Radyo', 'Kızılötesi', 'Görünür ışık'], 'NASA\'nın 1999\'da fırlattığı Chandra, kara delik çevreleri, süpernova kalıntıları ve sıcak gökada kümesi gazları gibi çok sıcak ortamları X ışınlarıyla inceler.'),
  ('Aşağıdaki gök olaylarından hangisini incelemek için X ışını gözlemi en uygundur?', 'Kara deliğe akan milyonlarca derecelik gaz', ['Soğuk moleküler bulutlar', 'Gezegenlerin yüzey renkleri', 'Samanyolu\'ndaki nötr hidrojen gazının 21 cm\'lik ışıması'], 'Çok sıcak gazlar (milyonlarca kelvin) ışınımlarının büyük bölümünü X ışınlarında yayar. Soğuk bulutlar ise kızılötesi ve radyoda incelenir.'),
  ('Birbirinden uzak birçok radyo teleskobunun birlikte çalışarak tek ve çok büyük bir teleskop gibi davranmasını sağlayan tekniğe ne ad verilir?', 'Girişimölçüm (interferometri)', ['Tayfölçüm', 'Uyarlamalı optik (adaptif optik)', 'Fotometri'], 'Girişimölçümde teleskoplar arasındaki en büyük uzaklık, ayırma gücünü belirleyen etkin çap gibi davranır. Olay Ufku Teleskobu kara delik gölgesinin görüntüsünü bu yöntemle elde etti.'),
  ('Bir yıldızın tayfında görülen karanlık soğurma çizgileri en doğrudan neyi ortaya koyar?', 'Yıldızın atmosferinde bulunan elementleri', ['Yıldızın kaç gezegeni olduğunu', 'Yıldızın yaşını kesin olarak', 'Yıldızın çevresindeki toz bulutunun tam biçimini ve dönüş yönünü'], 'Her element yalnızca kendine özgü dalga boylarında ışık soğurur. Bu çizgiler bir parmak izi gibi davranır ve yıldız atmosferindeki elementleri tanımamızı sağlar.'),
  ('Helyum elementi Dünya\'da bulunmadan önce ilk kez nerede saptanmıştır?', 'Güneş\'in tayfında', ['Ay\'dan getirilen kayaçlarda', 'Göktaşlarında', 'Jüpiter\'in uydularının yüzeyinde'], '1868 güneş tutulması sırasında Güneş\'in tayfında bilinen hiçbir elemente uymayan sarı bir çizgi görüldü; element adını Yunanca Güneş anlamına gelen "helios" sözcüğünden aldı.'),
  ('Sıcak ve seyrek bir gaz bulutu (örneğin bir bulutsu) koyu bir arka plan önünde gözlendiğinde nasıl bir tayf verir?', 'Parlak salma çizgilerinden oluşan bir tayf', ['Kesintisiz, çizgisiz bir tayf', 'Yalnızca karanlık soğurma çizgileri içeren bir tayf', 'Tamamen siyah, hiç ışık içermeyen bir tayf'], 'Uyarılmış atomlar belirli dalga boylarında ışık salar. Arkasında parlak bir kaynak olmayan seyrek sıcak gaz bu nedenle parlak çizgiler gösterir.'),
  ('Doppler etkisi ile bir yıldızın hangi hareketi ölçülebilir?', 'Bize doğru ya da bizden uzağa olan hareketi', ['Gökyüzünde yan yana kayışı', 'Kendi ekseni çevresindeki dönüşün yönünü tek başına', 'Yalnızca ufka göre yüksekliğinin değişimini'], 'Doppler kayması yalnızca bakış doğrultusundaki (dikine) hız bileşenini verir. Gökyüzü düzlemindeki hareket ise uzun süreli konum ölçümleriyle (öz hareket) belirlenir.'),
  ('Kadir sisteminde 5 kadirlik fark tam 100 kat parlaklık farkına karşılık gelir. 1 kadirlik bir yıldız, 6 kadirlik bir yıldızdan kaç kat parlaktır?', '100', ['5', '6', '500'], '6 − 1 = 5 kadir fark vardır ve tanım gereği bu 100 kat parlaklık farkı demektir.'),
  ('Bir kadirlik fark yaklaşık kaç kat parlaklık farkına karşılık gelir?', '2,5', ['1,5', '5', 'Yaklaşık 10'], '5 kadir 100 kat olduğundan 1 kadir 100\'ün beşinci kökü, yani yaklaşık 2,512 kat parlaklık farkı eder.'),
  ('Görünür kadir ile mutlak kadir arasındaki fark nedir?', 'Mutlak kadir, yıldızın 10 parsek uzaklıktan görüneceği parlaklıktır', ['Mutlak kadir, yıldızın çıplak gözle görülen parlaklığıdır', 'Görünür kadir, yıldızın gerçek ışıma gücüdür', 'İkisi aynı şeydir ama farklı ülkelerde farklı adlarla kullanılır'], 'Görünür kadir uzaklığa bağlıdır. Mutlak kadir ise tüm yıldızları aynı uzaklığa (10 parsek) koyarak gerçek ışıma güçlerini karşılaştırmayı sağlar.'),
  ('Bir yıldız gökyüzünde çok parlak görünüyor ve bir öğrenci bundan "Bu yıldız bize çok yakın olmalı" sonucunu çıkarıyor. Bu çıkarım neden güvenilir değildir?', 'Görünür parlaklık hem ışıma gücüne hem uzaklığa bağlıdır', ['Parlak yıldızlar her zaman en uzak yıldızlardır', 'Parlaklık yalnızca yıldızın rengine bağlıdır', 'Yakın yıldızlar çıplak gözle görülemez, yalnızca teleskopla seçilebilir'], 'Görünür parlaklık, yıldızın gerçekte ne kadar ışık yaydığına ve ne kadar uzakta olduğuna birlikte bağlıdır. Sönük ama yakın bir yıldız, güçlü ama uzak bir yıldızla aynı parlaklıkta görünebilir.'),
  ('Bir ışık kaynağının uzaklığı 3 katına çıkarılırsa görünür parlaklığı nasıl değişir?', 'Dokuzda birine iner', ['Üçte birine iner', 'Altıda birine iner', 'Hiç değişmez, çünkü ışığın gücü sabittir'], 'Işık her yöne yayıldığı için birim alana düşen ışık uzaklığın karesiyle ters orantılıdır: 1/3² = 1/9.'),
  ('Yakın yıldızların uzaklıklarını ölçmek için kullanılan ıraklık açısı (paralaks) yöntemi neye dayanır?', 'Dünya\'nın yörüngesindeki farklı konumlarından bakınca yakın yıldızın arka plana göre kayması', ['Yıldızların ışığının zamanla sönükleşmesi', 'Yıldızların renklerinin değişmesi', 'Yıldızlara gönderilen radar sinyallerinin geri dönüş süresi'], 'Altı ay arayla, Dünya yörüngesinin iki ucundan bakıldığında yakın bir yıldız uzak yıldızlara göre küçük bir açı kadar kayar. Bu açı ne kadar küçükse yıldız o kadar uzaktır.'),
  ('Parsek birimi nasıl tanımlanır?', 'Iraklık açısı 1 yay saniyesi olan bir yıldızın uzaklığı', ['Işığın bir saniyede aldığı yol', 'Güneş\'in çapının bir milyon katı', 'Samanyolu\'nun merkezine olan uzaklığın binde biri'], '"Paralaks" ve "saniye" sözcüklerinden türetilen parsek, yaklaşık 3,26 ışık yılına eşittir. Uzaklık (parsek) = 1 / ıraklık açısı (yay saniyesi).'),
  ('Iraklık açısı 0,25 yay saniyesi olarak ölçülen bir yıldızın uzaklığı kaç parsektir?', '4', ['0,25', '2,5', '25'], 'd = 1 / p bağıntısından d = 1 / 0,25 = 4 parsek bulunur; bu yaklaşık 13 ışık yılıdır.'),
  ('Paralaks yöntemi neden çok uzak yıldızlar için kullanılamaz?', 'Uzaklık arttıkça açı ölçülemeyecek kadar küçülür', ['Uzak yıldızlar hareket etmez', 'Uzak yıldızların ışığı Dünya\'ya ulaşmaz', 'Paralaks yalnızca gezegenlerde ve Ay\'da işe yarayan, yıldızlara hiç uygulanamayan bir yöntemdir'], 'Iraklık açısı uzaklıkla ters orantılıdır. Binlerce parsek ötedeki yıldızların açıları son derece küçüktür; Gaia gibi uydular bu sınırı genişletmiş olsa da çok uzak cisimler için başka yöntemler gerekir.'),
  ('Avrupa Uzay Ajansı\'nın Gaia uydusunun temel amacı nedir?', 'Bir milyardan fazla yıldızın konumunu ve uzaklığını hassas biçimde ölçmek', ['Mars\'a iniş yapmak', 'Güneş\'in tacını görüntülemek', 'Dünya\'nın iklimini izlemek ve okyanus sıcaklıklarını ölçmek'], 'Gaia, yüksek duyarlıklı ıraklık açısı ölçümleriyle Samanyolu\'nun üç boyutlu haritasını çıkarmak üzere tasarlanmış bir astrometri uydusudur.'),
  ('Wien yasasına göre bir yıldızın yüzey sıcaklığı iki katına çıkarsa en çok ışık yaydığı dalga boyu nasıl değişir?', 'Yarıya iner', ['İki katına çıkar', 'Dört katına çıkar', 'Hiç değişmez, yalnızca parlaklık değişir'], 'Wien yasası λ_maks × T = sabit biçimindedir; sıcaklık iki katına çıkınca tepe dalga boyu yarıya iner ve renk maviye kayar.'),
  ('Hertzsprung-Russell (H-R) diyagramında yıldızlar hangi iki özelliğe göre yerleştirilir?', 'Işıma gücü ve yüzey sıcaklığı', ['Kütle ve yaş', 'Uzaklık ve hız', 'Çap ve çevresinde dolanan gezegen sayısı'], 'H-R diyagramında dikey eksen ışıma gücünü (ya da mutlak kadiri), yatay eksen yüzey sıcaklığını (ya da tayf sınıfını) gösterir.'),
  ('H-R diyagramında sol alt köşede, yani sıcak ama çok sönük bölgede bulunan yıldızlar hangileridir?', 'Beyaz cüceler', ['Kırmızı devler', 'Mavi süperdevler', 'Kahverengi cüceler'], 'Sıcak ama sönük yıldızların yüzey alanı çok küçük olmalıdır; Dünya büyüklüğündeki beyaz cüceler bu bölgede yer alır.'),
  ('Ana koldaki bir yıldızın konumunu (sıcaklığını ve ışıma gücünü) en çok belirleyen özelliği nedir?', 'Kütlesi', ['Yaşı', 'Rengi', 'Gezegen sayısı'], 'Ana kol bir kütle dizisidir: kütleli yıldızlar sol üstte sıcak ve parlak, düşük kütleli yıldızlar sağ altta soğuk ve sönüktür.'),
  ('Çok kütleli bir yıldız daha fazla yakıta sahip olmasına karşın neden daha kısa yaşar?', 'Yakıtını kütlesiyle orantılı olandan çok daha hızlı tüketir', ['Yakıtı daha düşük kalitelidir', 'Çevresindeki gezegenler onun yakıtını çalar', 'Kütleli yıldızlar hiç kaynaşma yapmaz'], 'Işıma gücü kütleyle çok hızlı artar (yaklaşık kütlenin 3-4. kuvvetiyle). Örneğin 10 Güneş kütleli bir yıldız 10 kat yakıta sahipken binlerce kat hızlı harcar; ömrü milyonlarca yıla iner.'),
  ('Kütlesi bir yıldız olmaya yetmeyen, çekirdeğinde normal hidrojen kaynaşmasını sürdüremeyen ama gezegenlerden kütleli cisimlere ne ad verilir?', 'Kahverengi cüce', ['Beyaz cüce', 'Kırmızı cüce', 'Nötron yıldızı ya da atarca'], 'Kahverengi cüceler yaklaşık 13 ile 80 Jüpiter kütlesi arasındadır; hidrojen kaynaşmasını sürdüremezler ve zamanla soğuyup sönükleşirler.'),
  ('Kış gökyüzünde Orion\'un kılıcında çıplak gözle bulanık bir leke olarak görülebilen ünlü yıldız doğum bölgesinin adı nedir?', 'Orion Bulutsusu (M42)', ['Yengeç Bulutsusu (M1)', 'Andromeda Gökadası', 'Halka Bulutsusu'], 'Yaklaşık 1 300 ışık yılı uzaktaki Orion Bulutsusu, Dünya\'ya en yakın büyük yıldız oluşum bölgelerinden biridir ve içinde yeni doğmuş yıldızlar barındırır.'),
  ('Bir gaz bulutu çökerken neden giderek daha hızlı döner?', 'Açısal momentumun korunması', ['Enerjinin yok olması', 'Güneş rüzgârının itmesi', 'Bulutun kütlesinin çökme sırasında yüz kat artması'], 'Dönen bir buz patencisi kollarını kendine çektiğinde hızlanır. Çöken bulut da küçüldükçe açısal momentumunu koruyarak daha hızlı döner ve yassı bir diske dönüşür.'),
  ('Hubble\'ın Kartal Bulutsusu\'nda çektiği ünlü "Yaratılış Sütunları" fotoğrafında görülen yapılar nedir?', 'Yeni yıldızların oluştuğu yoğun gaz ve toz sütunları', ['Patlamış bir yıldızın enkazı', 'Bir kara deliğin fışkırttığı jetler', 'Samanyolu\'na çarpan bir gökadanın kollarının kalıntısı'], 'Bu sütunlar, yakındaki sıcak yıldızların ışınımıyla aşındırılan soğuk gaz ve toz kütleleridir; içlerinde yeni yıldızlar oluşmaktadır.'),
  ('Bir protoyıldızın gerçek bir yıldız sayılmaya başladığı an hangisidir?', 'Çekirdeğinde hidrojen kaynaşması başlayıp kararlı hâle geldiğinde', ['Işık yaymaya başladığında', 'Çevresindeki gezegenler oluştuğunda', 'İlk kez bir gaz bulutundan ayrılıp kendi yörüngesine oturduğunda'], 'Protoyıldız büzülürken de kütle çekim enerjisiyle parlar. Çekirdekte hidrojen kaynaşması başlayıp dışa doğru basınç çekimi dengelediğinde yıldız ana kola yerleşir.'),
  ('Genç yıldızların çevresinde sıkça gözlenen ve içinde gezegenlerin oluştuğu düşünülen yapıya ne ad verilir?', 'Öngezegen diski', ['Halka bulutsusu', 'Birikim kuşağı ve kuyruk', 'Oort bulutu'], 'Yıldız oluşumu sırasında artakalan madde yıldızın çevresinde dönen bir disk oluşturur. ALMA gibi teleskoplar bu disklerde gezegenlerin açtığı boşlukları görüntülemiştir.'),
  ('Yüksek kütleli yıldızlar genellikle tek başına değil, kümeler hâlinde doğar. Gözlenen genç yıldız kümelerinin üyeleri için hangisi beklenir?', 'Yaklaşık aynı yaşta, ama farklı kütlelerde olmaları', ['Tümünün aynı kütlede olması', 'Tümünün farklı bulutlardan gelmesi', 'Tümünün aynı anda süpernova olacağı'], 'Bir kümenin yıldızları aynı buluttan hemen hemen aynı anda doğar. Bu yüzden kümeler, yıldız evriminin kütleye bağımlılığını incelemek için ideal laboratuvarlardır.'),
  ('Beyaz cücelerle ilgili aşağıdakilerden hangisi doğrudur?', 'Kaynaşma yapmaz, depoladıkları ısıyı yayarak yavaşça soğurlar', ['Çekirdeklerinde hidrojen yakmayı sürdürürler', 'Güneş\'ten daha büyüktürler', 'Zamanla yeniden ana kol yıldızına dönüşürler'], 'Beyaz cüce, kaynaşmanın sona erdiği sıcak bir çekirdek kalıntısıdır. Yeni enerji üretmez; yalnızca ısısını yayarak çok uzun sürede soğur.'),
  ('Bir çay kaşığı beyaz cüce maddesinin Dünya\'da birkaç ton ağırlığında olacağı söylenir. Bu aşırı yoğunluğun nedeni nedir?', 'Güneş kütlesine yakın bir kütlenin Dünya boyutlarına sıkışması', ['Beyaz cücelerin tümüyle kurşundan oluşması', 'Beyaz cücelerin içinde kara delik bulunması', 'Beyaz cücenin sürekli dışarıdan madde yutması'], 'Beyaz cüceler Güneş kütlesinin büyük bir kısmını Dünya hacmi kadar bir alanda toplar; ortalama yoğunlukları suyunkinin yaklaşık milyon katıdır.'),
  ('Bir beyaz cücenin taşıyabileceği en büyük kütle sınırı (yaklaşık 1,4 Güneş kütlesi) hangi adla bilinir?', 'Chandrasekhar sınırı', ['Roche sınırı', 'Eddington sınırı', 'Schwarzschild yarıçapı'], 'Bu kütlenin üzerinde elektronların oluşturduğu yozlaşma basıncı çekime karşı koyamaz ve beyaz cüce çöker. Sınır adını Subrahmanyan Chandrasekhar\'dan alır.'),
  ('Vücudumuzdaki kalsiyum ve kanımızdaki demir gibi elementler için "yıldız tozundan yapılmışız" denir. Bu ifadenin bilimsel dayanağı nedir?', 'Bu elementler yıldızların içinde üretilip ölen yıldızlarca uzaya saçılmıştır', ['Bu elementler Büyük Patlama\'da doğrudan oluşmuştur', 'Bu elementler Dünya\'nın çekirdeğinde üretilir', 'Bu elementler yalnızca kuyruklu yıldızlarla taşınır'], 'Büyük Patlama\'da başlıca hidrojen ve helyum oluştu. Karbondan demire kadar elementler yıldızların çekirdeğinde, daha ağırlarının bir kısmı ise süpernovalarda ve nötron yıldızı birleşmelerinde üretildi.'),
  ('1054 yılında Çinli gökbilimcilerin gündüz bile görülebildiğini kaydettiği süpernovanın kalıntısı bugün hangi adla bilinir?', 'Yengeç Bulutsusu', ['Orion Bulutsusu', 'Halka Bulutsusu', 'Kartal Bulutsusu'], 'Boğa takımyıldızındaki Yengeç Bulutsusu (M1), 1054 süpernovasının genişleyen kalıntısıdır ve merkezinde hızla dönen bir atarca bulunur.'),
  ('Nova ile süpernova arasındaki temel fark nedir?', 'Nova bir beyaz cücenin yüzeyindeki patlamadır ve yıldızı yok etmez', ['Nova süpernovadan çok daha parlaktır', 'Nova yalnızca kırmızı devlerde olur', 'Nova bir yıldızın doğuşunu gösteren ilk parlamadır'], 'Çift sistemlerde beyaz cüce eşinden madde çeker; yüzeyde biriken hidrojen tutuşup patlar. Beyaz cüce bu patlamadan sağ çıkar ve olay tekrarlanabilir.'),
  ('Atarcalar (pulsarlar) nedir?', 'Işın demetleri Dünya\'yı tarayan, hızla dönen nötron yıldızları', ['Düzenli aralıklarla patlayan kırmızı devler', 'Yanıp sönen gezegenler', 'Yörüngesi Dünya\'yı her yıl bir kez kesen kuyruklu yıldızlar'], 'Atarcanın manyetik kutuplarından çıkan ışınım demetleri, deniz feneri gibi dönerek Dünya\'yı her taradığında düzenli bir atım algılanır.'),
  ('Bir nötron yıldızının saniyede yüzlerce kez dönebilmesinin nedeni nedir?', 'Çöken çekirdeğin küçülürken açısal momentumunu koruması', ['Nötronların kendiliğinden dönme eğilimi', 'Güneş rüzgârının nötron yıldızını döndürmesi', 'Nötron yıldızının içindeki gezegenlerin onu itmesi'], 'Yıldız çekirdeği yüz binlerce kilometreden yaklaşık 10 km yarıçapa çökerken, kollarını kapatan patenci gibi dönüş hızı muazzam ölçüde artar.'),
  ('Güneş bir anda aynı kütlede bir kara deliğe dönüşseydi, Dünya\'nın yörüngesine ne olurdu?', 'Yörünge değişmezdi; ama Dünya karanlıkta kalıp donardı', ['Dünya hemen kara deliğe çekilirdi', 'Dünya Güneş sisteminden fırlatılırdı', 'Dünya\'nın yörüngesi hızla daralıp bir yıl içinde içe düşerdi'], 'Uzaktan bakıldığında çekim yalnızca kütleye ve uzaklığa bağlıdır. Kütle aynı kaldıkça Dünya\'nın yörüngesi değişmezdi; ancak ışık ve ısı kaynağı ortadan kalkardı.'),
  ('Samanyolu\'nun merkezindeki süper kütleli kara deliğin adı nedir?', 'Sagittarius A*', ['Cygnus X-1 adlı X ışını kaynağı', 'M87*', 'Proxima b'], 'Sagittarius A* yaklaşık 4 milyon Güneş kütlesindedir. Varlığı, çevresinde hızla dolanan yıldızların yörüngeleri izlenerek kanıtlandı.'),
  ('2019\'da Olay Ufku Teleskobu ilk kez bir kara deliğin "gölgesinin" görüntüsünü yayımladı. Bu kara delik hangi gökadanın merkezindeydi?', 'M87', ['Andromeda', 'Samanyolu', 'Büyük Macellan Bulutu'], 'İlk görüntü, yaklaşık 55 milyon ışık yılı uzaktaki M87 gökadasının merkezindeki yaklaşık 6,5 milyar Güneş kütleli kara deliğe aitti. Samanyolu\'nun merkezindeki kara deliğin görüntüsü 2022\'de yayımlandı.'),
  ('2015\'te LIGO dedektörlerinin ilk kez doğrudan algıladığı kütle çekim dalgalarının kaynağı neydi?', 'Birbiri çevresinde dolanıp birleşen iki kara delik', ['Güneş\'teki bir patlama', 'Ay\'ın Dünya\'ya yaklaşması', 'Samanyolu\'nun merkezindeki yıldız oluşumu'], 'GW150914 adlı olayda yaklaşık 30\'ar Güneş kütlesindeki iki kara delik birleşti ve uzay-zamanda yayılan dalgalar Dünya\'ya 1,3 milyar yıl sonra ulaştı.'),
  ('Bir kara deliğe düşen gaz neden olay ufkuna ulaşmadan önce çok parlak X ışınları yayar?', 'Birikim diskinde sürtünmeyle milyonlarca dereceye ısınır', ['Gaz kara deliğe girince ışığa dönüşür', 'Kara delik gazı soğutur', 'Gaz olay ufkunda yansıyarak geri döner ve parlar'], 'Kara deliğe doğru sarmal çizerek düşen gaz bir disk oluşturur. Disk içindeki sürtünme ve sıkışma gazı çok ısıtır; bu da güçlü X ışını salımına yol açar.'),
  ('Kara deliklerin evrendeki her şeyi yutan "kozmik süpürgeler" olduğu düşüncesi neden yanlıştır?', 'Uzaktaki cisimler için çekimleri aynı kütleli bir yıldızınkinden farklı değildir', ['Kara delikler hiçbir şeyi çekmez', 'Kara delikler yalnızca ışığı çeker, maddeyi çekmez', 'Kara delikler her zaman eşleriyle birlikte yok olur ve geride hiçbir iz bırakmaz'], 'Kara delikler ancak çok yaklaşan maddeyi yakalar. Belirli bir uzaklıktan sonra çekimleri, aynı kütleli herhangi bir cisminkiyle aynıdır.'),
  ('Çift yıldız sistemleri, tek yıldızlarda doğrudan ölçülemeyen hangi özelliğin belirlenmesi açısından özellikle değerlidir?', 'Kütle', ['Renk', 'Görünür parlaklık', 'Gökyüzündeki konumu ve hangi takımyıldıza ait olduğu'], 'Yörünge dönemi ve yörünge boyutu ölçülünce Kepler\'in üçüncü yasasının Newton biçimiyle iki yıldızın toplam kütlesi hesaplanabilir.'),
  ('Bir çift yıldız sisteminde yıldızlardan biri düzenli aralıklarla öbürünün önünden geçerek toplam ışığı azaltıyorsa bu sisteme ne ad verilir?', 'Örten çift yıldız', ['Görsel çift', 'Optik çift', 'Tayfsal çift ve onun ikinci bileşeni'], 'Örten çiftlerin yörünge düzlemi bize göre neredeyse yandan görülür. Algol bu tür sistemlerin en ünlü örneğidir; parlaklığı yaklaşık 2,9 günde bir belirgin biçimde düşer.'),
  ('Gökyüzünde yan yana görünen ama gerçekte birbirinden çok farklı uzaklıkta olan ve birbirine bağlı olmayan iki yıldıza ne ad verilir?', 'Optik çift', ['Örten çift', 'Tayfsal çift', 'Değen çift'], 'Optik çiftler yalnızca bakış doğrultusunun rastlantısal çakışmasıdır; aralarında kütle çekimsel bir bağ yoktur.'),
  ('Sefeid değişen yıldızlarının uzaklık ölçümünde kullanılmasını sağlayan özellik nedir?', 'Parlaklık değişim dönemleri ile gerçek ışıma güçleri arasındaki ilişki', ['Renklerinin her zaman mavi olması', 'Tümünün Samanyolu\'nun merkezinde bulunması', 'Uzaklıkları arttıkça daha hızlı yanıp sönmeleri'], 'Henrietta Leavitt, Sefeidlerin dönemi uzadıkça ışıma güçlerinin arttığını buldu. Dönem ölçülünce ışıma gücü, oradan da görünür parlaklıkla karşılaştırılarak uzaklık bulunur.'),
  ('Yüz binlerce yaşlı yıldızın küre biçiminde sıkıca toplandığı ve Samanyolu\'nun çevresindeki halede dağılmış olarak bulunan yapılara ne ad verilir?', 'Küresel kümeler', ['Açık kümeler', 'Ana kol kümeleri', 'Yansıma bulutsuları ve onlara ait toz kuşakları'], 'Küresel kümeler evrenin en eski yıldızlarından bazılarını barındırır; yaşları 10 milyar yılı aşabilir.'),
  ('Samanyolu\'nun biçimi hangi gökada türüne uyar?', 'Çubuklu sarmal', ['Eliptik', 'Düzensiz', 'Mercek biçimli halka'], 'Gözlemler Samanyolu\'nun merkezinde bir yıldız çubuğu ve buradan çıkan sarmal kolları olan bir gökada olduğunu gösterir.'),
  ('Güneş, Samanyolu\'nun merkezinden yaklaşık ne kadar uzaktadır?', 'Yaklaşık 26 000 ışık yılı', ['Yaklaşık 260 ışık yılı', 'Yaklaşık 2,6 milyon ışık yılı', 'Yaklaşık 4,3 ışık yılı'], 'Güneş merkezden yaklaşık 8 kiloparsek, yani 26 000 ışık yılı kadar uzakta, kollardan birinin kenarında bulunur.'),
  ('Güneş, Samanyolu\'nun merkezi çevresindeki bir turunu yaklaşık ne kadar sürede tamamlar?', 'Yaklaşık 230 milyon yıl', ['Yaklaşık 1 milyon yıl', 'Yaklaşık 23 bin yıl', 'Yaklaşık 23 milyar yıl'], 'Güneş saniyede yaklaşık 220-230 km hızla dolanır; bir "gökada yılı" yaklaşık 225-250 milyon yıl sürer.'),
  ('Samanyolu\'nun merkezi gözle görülen ışıkta neden doğrudan incelenemez?', 'Aradaki yoğun toz görünür ışığı engeller', ['Merkez Güneş\'in arkasında kalır', 'Merkezde hiç yıldız yoktur', 'Merkez çok hızlı döndüğü için ışığı Dünya\'ya ulaşamaz'], 'Disk boyunca uzanan toz bulutları merkezden gelen görünür ışığı neredeyse tamamen soğurur. Kızılötesi, radyo ve X ışını gözlemleri bu perdeyi aşabilir.'),
  ('Samanyolu\'nun merkezi gökyüzünde hangi takımyıldız yönündedir?', 'Yay (Sagittarius)', ['Orion', 'Büyük Ayı', 'Kraliçe (Cassiopeia)'], 'Yaz akşamlarında güney ufkunda görülen Yay takımyıldızı yönünde Samanyolu kuşağı en parlak ve geniş hâlini alır; gökadanın merkezi bu yöndedir.'),
  ('Samanyolu\'nun diski, halesi ve merkezî şişkinliği karşılaştırıldığında yeni yıldız oluşumu en çok nerede sürmektedir?', 'Diskin sarmal kollarında', ['Halede', 'Küresel kümelerde', 'Merkezî şişkinliğin en dış kısmındaki yaşlı yıldızlar arasında'], 'Gaz ve toz büyük ölçüde disktedir; yıldız oluşumu da özellikle sarmal kollardaki yoğun bölgelerde yoğunlaşır. Halede ise çoğunlukla yaşlı yıldızlar bulunur.'),
  ('Güney Yarım Küre\'den çıplak gözle görülen ve Samanyolu\'nun uydu gökadaları olan iki düzensiz gökada hangileridir?', 'Büyük ve Küçük Macellan Bulutları', ['Andromeda ve Üçgen', 'Sombrero ve Girdap', 'M87 ve Centaurus A adlı dev eliptikler'], 'Macellan Bulutları, Samanyolu\'na yakın, düzensiz biçimli cüce gökadalardır ve güney gökyüzünde iki bulut parçası gibi görünür.'),
  ('Andromeda\'nın tayfında maviye kayma görülür. Bu bulgu neyi gösterir?', 'Andromeda\'nın Samanyolu\'na yaklaştığını', ['Andromeda\'nın evrenin genişlemesiyle hızla uzaklaştığını', 'Andromeda\'nın çok genç bir gökada olduğunu', 'Andromeda\'nın tüm yıldızlarının mavi olduğunu'], 'Andromeda saniyede yaklaşık 110 km hızla bize yaklaşmaktadır. Yakın gökadalarda yerel çekim, evrenin genişlemesinden baskın çıkar; iki gökadanın milyarlarca yıl sonra birleşmesi beklenir.'),
  ('Eliptik gökadalar sarmal gökadalarla karşılaştırıldığında genellikle hangi özelliği gösterir?', 'Az gaz ve toz içerir, yıldızları çoğunlukla yaşlıdır', ['Çok sayıda genç mavi yıldız içerir', 'Belirgin sarmal kollara sahiptir', 'Bol gaz ve tozla yoğun yıldız oluşumu sürdürür'], 'Eliptik gökadalarda yıldız oluşturacak soğuk gaz büyük ölçüde tükenmiştir; bu nedenle kırmızımsı, yaşlı yıldızlar baskındır.'),
  ('Samanyolu, Andromeda ve Üçgen gökadası ile onlarca cüce gökadadan oluşan küçük topluluğa ne ad verilir?', 'Yerel Grup', ['Başak Kümesi', 'Yerel Kabarcık', 'Gould Kuşağı ve ona komşu süper kümeler'], 'Yerel Grup, yaklaşık 10 milyon ışık yılı çapında bir bölgeye yayılan ve kütle çekimiyle bağlı bir gökada topluluğudur.'),
  ('Bir gökada kümesi, önündeki daha uzak bir gökadanın görüntüsünü yaylar ya da halkalar biçiminde bozuyor. Bu olaya ne ad verilir?', 'Kütle çekimsel mercek etkisi', ['Doppler etkisi', 'Işık kirliliği', 'Kromatik sapma ve onun neden olduğu renk saçılması'], 'Genel göreliliğe göre büyük kütleler uzay-zamanı büker ve yanından geçen ışığın yolunu saptırır. Bu etki, karanlık maddenin dağılımını haritalamak için de kullanılır.'),
  ('Merkezindeki süper kütleli kara deliğe düşen madde nedeniyle bütün gökadasından daha parlak olabilen çok uzak gökada çekirdeklerine ne ad verilir?', 'Kuasar', ['Atarca', 'Nova', 'Beyaz cüce'], 'Kuasarlar, etkin gökada çekirdeklerinin en parlak türüdür; çoğu milyarlarca ışık yılı uzaklıkta, yani evrenin genç döneminde görülür.'),
  ('Uzak gökadaların hepsinin bizden uzaklaşıyor görünmesi, Samanyolu\'nun evrenin merkezinde olduğunu gösterir mi?', 'Hayır; genişleyen uzayda her gözlemci aynı tabloyu görür', ['Evet; yalnızca merkezden bakılınca böyle görünür', 'Evet; Samanyolu en büyük gökada olduğu için', 'Hayır; aslında gökadalar bize yaklaşmaktadır ve kırmızıya kayma yanılsamadır'], 'Kabaran üzümlü bir kekte her üzüm diğerlerinin kendisinden uzaklaştığını görür. Genişleyen evrende de bir merkez yoktur; her gökadadan bakıldığında öbürleri uzaklaşır.'),
  ('Hubble yasasına göre, bizden 200 milyon ışık yılı uzaktaki bir gökada 100 milyon ışık yılı uzaktakine göre nasıl hareket eder?', 'Yaklaşık iki kat hızla uzaklaşır', ['Yarı hızla, yani daha yavaş uzaklaşır', 'Aynı hızla uzaklaşır', 'İki kat hızla yaklaşır'], 'Hubble yasası v = H₀ × d biçimindedir; uzaklık iki katına çıkınca uzaklaşma hızı da iki katına çıkar.'),
  ('Kozmik mikrodalga arka plan ışınımı (KMA) nedir?', 'Evrenin ilk dönemlerinden kalan ve her yönden gelen soğumuş ışınım', ['Güneş\'in yaydığı mikrodalgalar', 'Samanyolu\'nun merkezindeki kara delikten çıkan dalgalar', 'Dünya\'daki iletişim uydularının yaydığı yapay sinyaller'], 'Evren yaklaşık 380 000 yaşındayken ışık maddeden ayrıldı. Bu ışınım genişlemeyle uzayıp bugün yaklaşık 2,7 K sıcaklığa karşılık gelen mikrodalgalara dönüştü.'),
  ('Kozmik mikrodalga arka plan ışınımının bugünkü sıcaklığı yaklaşık kaç kelvindir?', '2,7', ['0', 'Yaklaşık 27', '273'], 'KMA\'nın tayfı yaklaşık 2,725 K sıcaklıktaki bir kara cisim tayfına neredeyse kusursuz biçimde uyar.'),
  ('Büyük Patlama\'dan sonraki ilk dakikalarda oluştuğu düşünülen başlıca hafif elementler hangileridir?', 'Hidrojen ve helyum', ['Karbon ve oksijen', 'Demir ve nikel', 'Altın, uranyum ve diğer ağır elementler'], 'İlk birkaç dakikadaki çekirdek oluşumu (nükleosentez) çoğunlukla hidrojen ve helyum ile az miktarda lityum üretti. Daha ağır elementler sonradan yıldızlarda oluştu.'),
  ('Gökada kümelerindeki gökadaların çok hızlı hareket etmesine karşın kümenin dağılmaması neyi düşündürür?', 'Kümede görünenden çok daha fazla kütle bulunduğunu', ['Gökadaların yavaşladığını', 'Kümelerin çok genç olduğunu', 'Gökadaların birbirini iterek dengede tuttuğunu'], '1930\'larda Fritz Zwicky, Koma Kümesi\'ndeki gökadaların hızlarının görünür kütleyle bir arada tutulamayacak kadar yüksek olduğunu fark etti; bu, karanlık madde düşüncesinin ilk ipuçlarından biridir.'),
  ('Bugünkü kozmolojik modele göre evrenin toplam enerji içeriğinin en büyük payı hangisine aittir?', 'Karanlık enerji', ['Sıradan (baryonik) madde', 'Karanlık madde', 'Işınım ve nötrinolar'], 'Standart modele göre evrenin yaklaşık %68\'i karanlık enerji, %27\'si karanlık madde, yalnızca %5\'i ise yıldızları, gezegenleri ve bizi oluşturan sıradan maddedir.'),
  ('Evrenin yaklaşık yalnızca %5\'inin sıradan maddeden oluştuğu bilgisi ne anlama gelir?', 'Evrenin büyük kısmı henüz doğası anlaşılmamış bileşenlerden oluşur', ['Evrenin %95\'i boşluktur ve hiçbir şey içermez', 'Evrende yalnızca yüzde beş oranında yıldız vardır', 'Gökbilimciler evrenin yalnızca %5\'ini gözlemleyebilmiştir, kalanı Dünya\'nın arkasında kalır'], 'Karanlık madde ve karanlık enerji gözlemlerle çıkarılan ama ne oldukları henüz bilinmeyen bileşenlerdir; bu durum modern fiziğin en büyük açık sorularından biridir.'),
  ('Hubble Derin Alan fotoğrafı için teleskop, gökyüzünün boş görünen küçük bir parçasına günlerce yöneltildi. Bu gözlemin şaşırtıcı sonucu neydi?', 'Bu küçük bölgede binlerce gökada görüldü', ['Hiçbir şey görülmedi', 'Yalnızca birkaç yakın yıldız görüldü', 'Bölgenin tümüyle tek bir kara delikten oluştuğu anlaşıldı'], '1995\'teki Hubble Derin Alan görüntüsü, gökyüzünün dolunay diskinden çok daha küçük bir bölgesinde 3 000 kadar gökada gösterdi; bu, evrendeki gökada sayısının ne kadar büyük olduğunu çarpıcı biçimde ortaya koydu.'),
  ('Ana kol yıldızı çevresinde dolanan ilk ötegezegenin keşfi 1995\'te hangi yıldızın çevresinde duyuruldu?', '51 Pegasi', ['Alfa Centauri A', 'Sirius', 'Vega'], 'Michel Mayor ve Didier Queloz, 51 Pegasi\'nin tayfındaki düzenli Doppler kaymalarından yola çıkarak bir "sıcak Jüpiter"in varlığını gösterdi; bu keşif 2019 Nobel Fizik Ödülü\'yle ödüllendirildi.'),
  ('Dikine hız (Doppler) yöntemiyle ötegezegen aramak neye dayanır?', 'Gezegenin çekimiyle yıldızın hafifçe ileri geri sallanmasına', ['Gezegenin yansıttığı ışığın doğrudan görülmesine', 'Gezegenin yıldızın önünden geçmesine', 'Gezegenin ürettiği radyo sinyallerinin alınmasına'], 'Yıldız ve gezegen ortak kütle merkezi çevresinde dolanır. Yıldızın bize yaklaşıp uzaklaşması tayf çizgilerinde küçük ve düzenli kaymalar yaratır.'),
  ('Geçiş yöntemi neden tüm ötegezegenleri saptayamaz?', 'Yalnızca yörüngesi bize göre yandan görülen sistemlerde geçiş olur', ['Geçişler yalnızca kırmızı cücelerde görülür', 'Büyük gezegenler hiç geçiş yapmaz', 'Geçiş yöntemi yalnızca Güneş sisteminin içinde çalışır'], 'Geçiş görülebilmesi için gezegenin yörünge düzleminin bakış doğrultumuzla neredeyse aynı hizada olması gerekir; bu da sistemlerin yalnızca küçük bir kısmında sağlanır.'),
  ('Binlerce ötegezegenin geçiş yöntemiyle keşfedilmesini sağlayan ve 2009-2018 arasında çalışan NASA uzay teleskobu hangisidir?', 'Kepler', ['Hubble', 'Chandra', 'Spitzer'], 'Kepler Uzay Teleskobu, gökyüzünün bir bölgesindeki yaklaşık 150 000 yıldızın parlaklığını sürekli izleyerek binlerce ötegezegen ve aday keşfetti.'),
  ('"Sıcak Jüpiter" olarak adlandırılan ötegezegenlerin özelliği nedir?', 'Jüpiter büyüklüğünde olup yıldızlarına çok yakın dolanmaları', ['Yüzeylerinde lav okyanusları bulunan küçük kaya gezegenleri olmaları', 'Jüpiter\'in uydularına benzemeleri', 'Yıldızlarından çok uzakta, buzla kaplı dev gezegenler olmaları'], 'Bu dev gezegenler yıldızlarına Merkür\'ün Güneş\'e uzaklığından bile daha yakın dolanır ve birkaç günlük yörünge dönemlerine sahiptir. Güneş sisteminde benzerleri yoktur.'),
  ('Kırmızı cücelerin çevresindeki yaşanabilir bölge, Güneş\'inkine göre nerededir?', 'Yıldıza çok daha yakın', ['Yıldızdan çok daha uzak', 'Güneş\'inkiyle tamamen aynı uzaklıkta', 'Kırmızı cücelerin hiç yaşanabilir bölgesi yoktur'], 'Kırmızı cüceler Güneş\'ten çok daha sönüktür; bir gezegenin yeterince ısınması için yıldıza çok yakın dolanması gerekir.'),
  ('Dünya\'ya en yakın yıldız olan Proxima Centauri\'nin çevresinde keşfedilen ve yaşanabilir bölgede bulunan gezegen hangisidir?', 'Proxima b', ['Kepler-22b', '51 Pegasi b', 'TRAPPIST-1e'], 'Proxima b, 2016\'da dikine hız yöntemiyle bulundu; yaklaşık 4,2 ışık yılı uzaklıktaki Proxima Centauri\'nin yaşanabilir bölgesinde, yaklaşık 11 günlük yörüngede dolanır.'),
  ('Yaklaşık 40 ışık yılı uzaktaki ve en az yedi Dünya büyüklüğünde gezegeni olduğu bilinen kırmızı cüce sistemi hangisidir?', 'TRAPPIST-1', ['Alfa Centauri', 'Kepler-452', 'Barnard Yıldızı'], 'TRAPPIST-1\'in yedi kaya gezegeni 2017\'de duyuruldu; bunların birkaçı yıldızın yaşanabilir bölgesinde yer alır.'),
  ('Bir ötegezegenin atmosferinin bileşimi gökbilimciler tarafından nasıl incelenebilir?', 'Geçiş sırasında atmosferden süzülen yıldız ışığının tayfı alınarak', ['Gezegenden örnek getirilerek', 'Gezegene radar gönderilerek', 'Gezegenin kütle çekim dalgaları ölçülerek'], 'Geçiş sırasında yıldız ışığının bir kısmı gezegenin atmosferinden geçer; atmosferdeki moleküller belirli dalga boylarını soğurur. JWST bu yöntemle su, karbondioksit gibi molekülleri saptamıştır.'),
  ('Kahverengi cüceler ve büyük ötegezegenler bazen doğrudan görüntülenebilir. Doğrudan görüntülemeyi zorlaştıran temel sorun nedir?', 'Yıldızın parlaklığının gezegenin ışığını bastırması', ['Gezegenlerin yıldızlardan daha parlak olması', 'Gezegenlerin yalnızca radyo dalgası yayması', 'Gezegenlerin ışık hızından hızlı hareket etmesi'], 'Bir yıldız gezegeninden milyonlarca, hatta milyarlarca kat parlaktır. Bu yüzden yıldız ışığını engelleyen koronagraflar ve kızılötesi gözlemler gerekir.'),
  ('Bir ötegezegenin yarıçapı geçiş yöntemiyle, kütlesi dikine hız yöntemiyle ölçülmüşse gökbilimciler bu iki bilgiyi birleştirerek neyi hesaplayabilir?', 'Ortalama yoğunluğunu ve dolayısıyla olası yapısını', ['Yaşını ve oluşum tarihini kesin olarak', 'Uydu sayısını', 'Yüzeyinde yaşam olup olmadığını'], 'Kütle ve yarıçaptan hacim ve yoğunluk bulunur. Yoğunluk, gezegenin kayalık mı, sulu mu yoksa gaz ağırlıklı mı olduğuna dair önemli ipuçları verir.'),
  ('1977\'de fırlatılan ve heliopozu geçerek yıldızlar arası ortama ulaşan ilk insan yapımı cisim olan uzay aracı hangisidir?', 'Voyager 1', ['Pioneer 11', 'Voyager 2', 'New Horizons'], 'Voyager 1, 2012\'de heliopozu geçerek yıldızlar arası uzaya ulaşan ilk araç oldu; Jüpiter ve Satürn\'ün yanından geçerek bu gezegenlerin ayrıntılı görüntülerini göndermişti.'),
  ('Voyager 1\'in 1990\'da yaklaşık 6 milyar km uzaktan çektiği ve Dünya\'nın küçük bir ışık noktası olarak göründüğü ünlü fotoğraf hangi adla bilinir?', 'Soluk Mavi Nokta', ['Mavi Bilye', 'Dünya\'nın Doğuşu', 'Yaratılış Sütunları'], 'Carl Sagan\'ın önerisiyle çekilen "Soluk Mavi Nokta" fotoğrafında Dünya bir pikselden küçük bir nokta olarak görünür.'),
  ('Dış Güneş sistemine giden Voyager gibi araçlar enerji için güneş paneli yerine neden radyoizotop jeneratörleri (RTG) kullanır?', 'Güneş\'ten uzaklaştıkça güneş ışığı çok zayıflar', ['Güneş panelleri uzayda donar', 'RTG\'ler daha hafiftir ve hiç ısı üretmez', 'Güneş panelleri yalnızca Dünya\'nın atmosferi içinde çalışabilir'], 'Güneş ışığının şiddeti uzaklığın karesiyle azalır; Jüpiter\'de bile Dünya\'dakinin yaklaşık 1/27\'sidir. RTG\'ler plütonyum-238\'in bozunmasından çıkan ısıyı elektriğe çevirir.'),
  ('Satürn sistemini 2004-2017 yılları arasında yörüngeden inceleyen ve Titan\'a Huygens adlı bir iniş aracı bırakan görev hangisidir?', 'Cassini-Huygens', ['Galileo', 'Juno', 'Voyager 2 ve Pioneer 11'], 'Cassini, Satürn\'ün halkalarını ve uydularını 13 yıl boyunca inceledi; Huygens 2005\'te Titan\'ın yüzeyine indi. Görev, Cassini\'nin bilerek Satürn atmosferine dalmasıyla sona erdi.'),
  ('Cassini uzay aracının görevi bitince Satürn atmosferine bilerek düşürülmesinin nedeni neydi?', 'Enceladus ve Titan gibi uyduları Dünya mikroplarıyla kirletme riskini önlemek', ['Aracın yeniden kullanılmak üzere toplanması', 'Satürn\'ün halkalarını yok etmek', 'Aracın Dünya\'ya geri dönmesini sağlamak'], 'Yaşam barındırma olasılığı olan uydulara kontrolsüz bir çarpma, oralara Dünya kökenli mikroorganizma taşıyabilirdi. Bu "gezegen koruma" ilkesi gereği yakıtı biten araç Satürn\'de yok edildi.'),
  ('2016\'dan bu yana Jüpiter\'in çevresinde kutuptan kutba uzanan bir yörüngede dolanan NASA aracı hangisidir?', 'Juno', ['Galileo', 'Cassini', 'Dawn'], 'Juno, Jüpiter\'in iç yapısını, manyetik alanını ve kutup bölgelerini incelemek üzere tasarlanmıştır; güneş panelleriyle çalışan en uzak araçlardandır.'),
  ('Güneş\'in tacına daha önce hiçbir aracın yaklaşmadığı kadar yaklaşmak üzere tasarlanan NASA aracı hangisidir?', 'Parker Güneş Sondası', ['SOHO', 'Ulysses', 'Solar Orbiter ve onun ikiz aracı'], '2018\'de fırlatılan Parker Güneş Sondası, Güneş\'in dış atmosferinin içinden geçerek güneş rüzgârının nasıl hızlandığını inceler; kalın bir ısı kalkanıyla korunur.'),
  ('Bir uzay aracının Venüs yüzeyinde uzun süre çalışmasını neredeyse imkânsız kılan iki temel koşul hangileridir?', 'Çok yüksek sıcaklık ve ezici atmosfer basıncı', ['Aşırı soğuk ve güçlü manyetik alan', 'Su baskınları ve yoğun kar yağışı', 'Atmosfer olmaması ve sürekli göktaşı yağmuru'], 'Venera serisi gibi Sovyet araçları Venüs yüzeyinde ancak bir-iki saat dayanabildi; yaklaşık 460 °C sıcaklık ve 90 atmosferlik basınç elektroniği kısa sürede bozar.'),
  ('Apollo 13 görevi Ay\'a inemeden geri dönmek zorunda kaldı. Bunun nedeni neydi?', 'Servis modülündeki bir oksijen tankının patlaması', ['Ay\'da iniş yerinin bulunamaması', 'Astronotlardan birinin hastalanması', 'Roketin fırlatma rampasında alev alması'], 'Yolculuğun üçüncü gününde oksijen tankı patladı. Mürettebat Ay modülünü cankurtaran olarak kullanıp Ay\'ın çevresinden dolanarak güvenle Dünya\'ya döndü.'),
  ('Uluslararası Uzay İstasyonu bazen gece gökyüzünde çıplak gözle çok parlak, hızla kayan bir ışık olarak görülür. Bu genellikle ne zaman olur?', 'Gün batımından sonra ya da gün doğumundan önce', ['Gece yarısında, gökyüzü en karanlıkken', 'Öğle vakti', 'Yalnızca tam Güneş tutulmasında'], 'İstasyon kendi ışığını yaymaz, güneş ışığını yansıtır. Yerde hava kararmışken yüksekteki istasyon hâlâ güneş ışığı alıyorsa parlak görünür; gece yarısı ise genellikle Dünya\'nın gölgesindedir.'),
  ('Bir telefonun GPS ile konumunu belirlemesi hangi ilkeye dayanır?', 'Birkaç uydudan gelen sinyallerin ulaşma sürelerinin karşılaştırılması', ['Uyduların telefonu fotoğraflaması', 'Telefonun Dünya\'nın manyetik alanını ölçmesi', 'Uyduların yıldızların konumunu telefona bildirmesi'], 'Her GPS uydusu çok hassas saat bilgisi yayınlar. Alıcı en az dört uydudan gelen sinyallerin gecikmesinden uzaklıkları hesaplayıp konumunu bulur.'),
  ('Roket fırlatma alanlarının genellikle ekvatora yakın yerlere kurulmasının ve roketlerin doğuya doğru fırlatılmasının nedeni nedir?', 'Dünya\'nın dönüş hızından ek hız kazanmak', ['Ekvatorda hava daha soğuk olduğu için', 'Ekvatorda yerçekimi hiç bulunmadığı için', 'Doğu yönünde Güneş\'in roketi itmesi'], 'Ekvatordaki bir nokta Dünya\'nın dönüşüyle saatte yaklaşık 1 670 km hızla doğuya hareket eder. Doğuya fırlatılan roket bu hızı başlangıçta bedavaya kazanır.'),
  ('Bir astronot uzay istasyonunda uzun süre kaldıktan sonra Dünya\'ya döndüğünde kemik ve kas kaybı yaşar. Bu durumun temel nedeni nedir?', 'Ağırlıksız ortamda kemik ve kasların yük taşımaması', ['Uzaydaki besinlerin kalsiyum içermemesi', 'Uzay istasyonunda oksijenin az olması', 'Kozmik ışınların kemikleri doğrudan eritmesi'], 'Kemik ve kaslar kullanıldıkça güçlenir. Serbest düşüş ortamında vücut ağırlığını taşımadığı için yoğunluk ve kütle kaybedilir; astronotlar bu yüzden her gün spor yapar.'),
  ('Japonya\'nın Hayabusa2 ve NASA\'nın OSIRIS-REx görevlerinin ortak başarısı nedir?', 'Bir asteroitten örnek alıp Dünya\'ya getirmek', ['Mars\'a insan indirmek', 'Jüpiter\'in uydusuna inmek', 'Güneş\'ten parçacık örneği toplayıp geri getirmek'], 'Hayabusa2 Ryugu\'dan, OSIRIS-REx ise Bennu\'dan örnek toplayarak Dünya\'ya getirdi; bu örnekler Güneş sisteminin erken dönem maddesini inceleme olanağı sağlar.'),
  ('Kentlerden uzakta, gökyüzünün doğal karanlığını korumak amacıyla resmî olarak belirlenen alanlara ne ad verilir?', 'Karanlık gökyüzü parkı', ['Ulusal gözlem müzesi', 'Yıldız kütüphanesi', 'Kuzey ışıkları koruma bölgesi ve kutup kampı'], 'Uluslararası Karanlık Gökyüzü kuruluşunun ölçütlerini karşılayan alanlar karanlık gökyüzü parkı ya da koruma alanı olarak tanınır ve gece aydınlatması denetlenir.'),
  ('Ay\'ın kraterlerini teleskopla gözlemek için dolunay neden en uygun zaman değildir?', 'Güneş tepeden vurduğu için gölgeler yok olur ve kabartılar seçilmez', ['Dolunayda Ay\'ın yüzeyi tümüyle bulutla kaplanır', 'Dolunayda Ay çok küçük görünür', 'Dolunayda Ay ufkun altında kalır'], 'Kraterler en iyi aydınlık ile karanlığın sınırı olan sonlandırıcı çizgi boyunca, uzun gölgeler düştüğünde görülür; dolunayda ışık dik geldiği için yüzey düz görünür.'),
  ('Ufka yakın görünen Ay\'ın tepedeyken olduğundan daha büyük göründüğü sanılır. Bu "Ay yanılsaması" için hangisi doğrudur?', 'Bir algı yanılsamasıdır; Ay\'ın açısal büyüklüğü neredeyse değişmez', ['Atmosfer bir büyüteç gibi Ay\'ı büyütür', 'Ay ufka yakınken Dünya\'ya gerçekten daha yakındır', 'Ay her akşam şişip sabah küçülür'], 'Fotoğraflarla ölçüldüğünde ufuktaki Ay tepedekinden büyük değildir; hatta biraz daha uzaktadır. Etki, beynin ufku ve çevresindeki nesneleri değerlendirme biçiminden kaynaklanır.'),
  ('Gökbilimcilerin "görüş" (seeing) olarak adlandırdığı kavram neyi anlatır?', 'Atmosferin durgunluğuna bağlı görüntü keskinliğini', ['Gökyüzünün ne kadar bulutlu olduğunu', 'Gözlemcinin göz numarasını', 'Teleskobun ne kadar ağır olduğunu ve taşınabilirliğini'], 'İyi görüşlü bir gecede atmosfer durgundur ve yıldızlar keskin noktalar olarak görülür. Kötü görüşte hava türbülansı görüntüleri titretip bulanıklaştırır.'),
  ('Çıplak gözle gece gökyüzünde parlak bir "yıldızın" gezegen olup olmadığını anlamak için kullanılan basit ipuçlarından biri hangisidir?', 'Gezegenler yıldızlara göre daha az titreşir', ['Gezegenler her zaman kutup çevresindedir', 'Gezegenler yalnızca kuzey ufkunda görülür', 'Gezegenler her gece aynı saatte tam olarak başucunda bulunur'], 'Gezegenler küçük bir disk olarak göründüğü için atmosferin titreştirme etkisi ortalanır ve ışıkları daha sakin görünür. Ayrıca ekliptiğe yakın bulunurlar ve haftalar içinde yıldızlara göre yer değiştirirler.'),
  ('Bir amatör gökbilimci yaz gecesi doğu ufkundan yükselen, renkli ve titrek görünen parlak bir yıldızı UFO sanıyor. Bu yanılgının en olası nedeni nedir?', 'Ufka yakın yıldız ışığının kalın atmosferden geçerken titreyip renk değiştirmesi', ['Yıldızın gerçekten renk değiştiren bir uzay aracı olması', 'Yıldızın çok hızlı dönen bir gezegen olması', 'Yıldızın Dünya\'ya hızla yaklaşması ve büyümesi'], 'Ufka yakın yıldızların ışığı daha çok hava katmanından geçer; türbülans ve kırılma ışığı renklere ayırarak titretir. Bu doğal olay sıkça yanlış yorumlanır.'),
  ('Uzun pozlamalı gökyüzü fotoğraflarında bazen yıldızları kesen düz, parlak çizgiler görülür. Son yıllarda bu çizgilerin en sık nedeni hangisidir?', 'Alçak yörüngedeki uydu takımları', ['Kuyruklu yıldızların bıraktığı toz izleri', 'Gezegenlerin geri devinimi', 'Süpernova patlamaları'], 'Güneş ışığını yansıtan binlerce alçak yörünge uydusu, özellikle gün batımından sonraki saatlerde fotoğraflarda iz bırakır ve gökbilimsel gözlemleri olumsuz etkiler.'),
  ('Işığın Ay\'dan Dünya\'ya ulaşması yaklaşık ne kadar sürer?', 'Yaklaşık 1,3 saniye', ['Yaklaşık 8 dakika', 'Yaklaşık 13 saniye', 'Yaklaşık 0,13 saniye'], '384 400 km / 300 000 km/s ≈ 1,28 saniye. Apollo astronotlarıyla yapılan konuşmalarda bu yüzden gidiş-dönüş yaklaşık 2,6 saniyelik gecikme olurdu.'),
  ('Jüpiter Güneş\'ten yaklaşık 5,2 AB uzaklıktadır. Güneş ışığı Jüpiter\'e yaklaşık ne kadar sürede ulaşır?', 'Yaklaşık 43 dakika', ['Yaklaşık 8 dakika', 'Yaklaşık 5 saat', 'Yaklaşık 2 dakika 30 saniye'], 'Işığın 1 AB\'yi alması yaklaşık 8,3 dakika sürer: 5,2 × 8,3 ≈ 43 dakika.'),
  ('Güneş bir futbol topu (yaklaşık 22 cm çapında) büyüklüğüne küçültülseydi, Dünya bu ölçekte yaklaşık ne büyüklükte olurdu?', 'Yaklaşık 2 mm, bir toplu iğne başı kadar', ['Yaklaşık 2 cm, bir bilye kadar', 'Yaklaşık 11 cm, bir portakal kadar', 'Yaklaşık 22 cm, Güneş ile aynı'], 'Güneş\'in çapı Dünya\'nınkinin yaklaşık 109 katıdır: 22 cm / 109 ≈ 0,2 cm, yani yaklaşık 2 mm.'),
  ('Güneş\'in çapı Dünya\'nınkinin yaklaşık 109 katıdır. Güneş\'in içine kabaca kaç Dünya sığar?', 'Yaklaşık 1,3 milyon', ['Yaklaşık 109', 'Yaklaşık 12 000', 'Yaklaşık 1,3 milyar Dünya'], 'Hacim çapın küpüyle orantılıdır: 109³ ≈ 1 295 000, yani yaklaşık 1,3 milyon Dünya.'),
  ('Uranüs\'ün büyük uydularının çoğu hangi kaynaktan ad almıştır?', 'Shakespeare ve Pope\'un yapıtlarındaki karakterlerden', ['Yunan tanrılarından', 'Ünlü gökbilimcilerden', 'Türk destanlarındaki kahramanlardan ve onların atlarından'], 'Titania, Oberon, Miranda, Ariel ve Umbriel gibi adlar William Shakespeare ile Alexander Pope\'un eserlerindeki karakterlerden alınmıştır.'),
  ('Uranüs çıplak gözle görülebilir mi?', 'Çok karanlık bir gökyüzünde, yerini bilen için güçlükle görülebilir', ['Her gece en parlak gezegen olarak kolayca görülür', 'Hiçbir koşulda dürbünle bile görülemez', 'Yalnızca gündüz, Güneş\'in yanında görülebilir'], 'Uranüs\'ün parlaklığı yaklaşık 5,7 kadirdir; çıplak göz sınırına yakın olduğundan çok karanlık bir gökyüzünde zor da olsa seçilebilir. Bu sönüklük, eskiçağda gezegen olarak tanınmamasını açıklar.'),
  ('Satürn\'ün halkalarındaki bazı ince halkaların kenarlarını keskin tutan ve halka maddesini bir arada tutmaya yardım eden küçük uydulara ne ad verilir?', 'Çoban uydular', ['Truva uyduları', 'Düzensiz uydular', 'Gezegen kalkanları ve onları çevreleyen toz kuşakları'], 'Prometheus ve Pandora gibi küçük uydular F halkasının iki yanında dolanarak kütle çekimleriyle halka parçacıklarını dar bir şeritte tutar.'),
  ('Algol yıldızı Arapçada "şeytanın başı" anlamına gelen bir adla bilinir. Bu yıldızın parlaklığı neden birkaç günde bir belirgin biçimde düşer?', 'Sönük eşi her turunda parlak yıldızın önünden geçer', ['Yıldız her üç günde bir küçülür', 'Önünden Dünya\'nın uydusu geçer', 'Yıldız düzenli olarak gaz kabuğunu dışarı atar'], 'Algol örten bir çift yıldızdır: daha sönük bileşen yaklaşık 2,87 günde bir parlak bileşenin önünden geçerek toplam ışığı azaltır.'),
  ('Bazı kırmızı dev yıldızlar aylarca süren dönemlerle büyük parlaklık değişimleri gösterir. Balina takımyıldızındaki bu türün ilk örneği olan ve "harika" anlamına gelen yıldız hangisidir?', 'Mira', ['Vega', 'Rigel', 'Deneb'], 'Mira yaklaşık 332 günlük dönemle çıplak gözle görülebilir parlaklıktan görünmez olacak kadar sönük bir duruma gelip geri döner; bu türe Mira değişenleri denir.'),
  ('Sefeid değişen yıldızlarında parlaklık değişiminin fiziksel nedeni nedir?', 'Yıldızın düzenli olarak genişleyip büzülmesi', ['Önünden gezegen geçmesi', 'Yıldızın patlayıp yeniden oluşması', 'Bir eşin onu düzenli olarak örtmesi'], 'Sefeidler zonklayan (titreşen) yıldızlardır; dış katmanlar düzenli olarak şişip küçülür, yüzey sıcaklığı ve boyutu değiştikçe parlaklık da değişir.'),
  ('Gökbilimciler yıldızlardan gelen ışığın tayfını inceleyerek aşağıdakilerden hangisini belirleyemez?', 'Yıldızın kaç yıl sonra öleceğini kesin tarihle', ['Yıldızın yüzey sıcaklığını', 'Yıldızın kimyasal bileşimini', 'Yıldızın bize yaklaşıp uzaklaştığını'], 'Tayf sıcaklık, bileşim ve dikine hız gibi bilgileri doğrudan verir. Ölüm zamanı ise ancak modellerle, belirsizlik payıyla tahmin edilebilir.'),
  ('Atarcaların atım dönemleri çok kararlıdır. Bu özellik onları hangi amaçla kullanılabilir kılar?', 'Çok hassas kozmik saatler olarak', ['Güneş\'in yaşını ve kütlesini ölçmede', 'Bulutların hareketini izlemede', 'Ay\'ın evrelerini hesaplamada'], 'Bazı milisaniye atarcalarının dönemi atomik saatlerle yarışacak kararlılıktadır. Bu saatlerdeki çok küçük düzensizlikler kütle çekim dalgalarını ve gezegenleri ortaya çıkarabilir; ilk ötegezegenler de bir atarca çevresinde bulunmuştur.'),
  ('Karanlık madde ile karanlık enerjinin evren üzerindeki etkileri nasıl karşılaştırılır?', 'Karanlık madde çekerek toplar, karanlık enerji genişlemeyi hızlandırır', ['İkisi de evrenin genişlemesini yavaşlatır', 'Karanlık madde ışık yayar, karanlık enerji yaymaz', 'İkisi de aynı şeydir ve farklı adlarla anılır'], 'Karanlık madde sıradan madde gibi kütle çekimi uygular ve gökadaların bir arada kalmasına yardım eder. Karanlık enerji ise büyük ölçekte uzayı birbirinden uzaklaştıran bir etki gibi davranır.'),
  ('Bir gözlemcinin bulunduğu yerde kuzey ve güney noktalarından ve başucundan geçen büyük çembere ne ad verilir?', 'Gök meridyeni', ['Ekliptik', 'Gök ekvatoru', 'Ufuk çemberi ya da gözlem ufku'], 'Bir gök cismi gün içinde meridyeni geçerken en yüksek noktasına ulaşır; Güneş\'in meridyenden geçtiği an yerel öğledir.'),
  ('Kuzey Kutbu\'nda duran bir gözlemci için gökyüzündeki yıldızlar nasıl hareket eder?', 'Ufka paralel çemberler çizerek hiç doğup batmaz', ['Doğudan doğup batıdan batar', 'Dik açıyla doğup dik açıyla batar', 'Kuzeyden doğup güneyden batar'], 'Kutupta gök kutbu başucundadır; tüm yıldızlar ufka paralel daireler çizer. Görülebilen yıldızlar hiç batmaz, ufkun altındakiler hiç doğmaz.'),
  ('Kış gökyüzünde Orion\'un kemerini oluşturan üç yıldızın çizdiği doğru kuzeybatıya doğru uzatıldığında ulaşılan, Boğa takımyıldızının turuncu-kırmızı parlak yıldızı hangisidir?', 'Aldebaran', ['Vega', 'Deneb', 'Arcturus'], 'Orion\'un kemeri, gökyüzünde yol bulmak için iyi bir kılavuzdur: kuzeybatıya uzatıldığında Aldebaran\'a ve ardından Ülker kümesine, güneydoğuya uzatıldığında ise Sirius\'a ulaşılır.'),
  ('Yaz akşamları başucuna yakın görülen ve Vega, Deneb ve Altair yıldızlarının oluşturduğu büyük üçgen desene ne ad verilir?', 'Yaz Üçgeni', ['Kış Altıgeni', 'Kuzey Haçı', 'Büyük Kare'], 'Çalgı takımyıldızından Vega, Kuğu\'dan Deneb ve Kartal\'dan Altair, yaz gökyüzünün en belirgin deseni olan Yaz Üçgeni\'ni oluşturur.'),
  ('Yıldızlara göre ölçüldüğünde Dünya\'nın kendi ekseni çevresinde bir kez dönmesi ne kadar sürer?', 'Yaklaşık 23 saat 56 dakika', ['Tam 24 saat', 'Yaklaşık 24 saat 4 dakika', 'Yaklaşık 23 saat 4 dakika 30 saniye'], 'Bu süreye yıldız günü denir. Güneş\'i yeniden aynı konumda görmek için Dünya\'nın yaklaşık 4 dakika daha dönmesi gerektiğinden güneş günü 24 saattir.'),
  ('Dünya Güneş çevresindeki yörüngesinde saniyede yaklaşık kaç kilometre hızla ilerler?', '30', ['0,5', '3', '300'], 'Yörünge çevresi yaklaşık 2π × 150 milyon km ≈ 940 milyon km\'dir. Bu yolu bir yılda (yaklaşık 31,6 milyon saniyede) almak saniyede yaklaşık 30 km hız gerektirir.'),
  ('Dünya\'ya en çok yaklaşabilen gezegen hangisidir?', 'Venüs', ['Mars', 'Merkür', 'Jüpiter'], 'Venüs, Güneş ile Dünya arasından geçerken Dünya\'ya yaklaşık 38-40 milyon km\'ye kadar yaklaşabilir; bu, başka hiçbir gezegenin ulaşamadığı bir yakınlıktır.'),
  ('Neptün\'de Voyager 2\'nin 1989\'da gözlediği ve sonraki yıllarda kaybolduğu görülen büyük fırtınaya ne ad verilmiştir?', 'Büyük Kara Leke', ['Büyük Kırmızı Leke', 'Büyük Beyaz Leke', 'Kutup Altıgeni'], 'Neptün\'ün Büyük Kara Lekesi, Jüpiter\'deki Büyük Kırmızı Leke\'den farklı olarak birkaç yıl içinde kayboldu; Hubble daha sonra başka kara lekeler gözledi.'),
  ('Uluslararası kabul gören bir tanıma göre uzayın başlangıcı sayılan ve deniz seviyesinden yaklaşık 100 km yükseklikte bulunan sınırın adı nedir?', 'Kármán çizgisi', ['Roche sınırı', 'Heliopoz', 'Van Allen sınırı'], 'Kármán çizgisi, uçakların kanatlarıyla tutunabileceği havanın neredeyse bittiği yaklaşık 100 km yüksekliği uzayın başlangıcı olarak kabul eder.'),
  ('Dünya\'yı çevreleyen ve Güneş\'ten gelen yüklü parçacıkları yakalayan iki büyük ışınım kuşağına ne ad verilir?', 'Van Allen kuşakları', ['Kuiper kuşakları', 'Kirkwood kuşakları', 'Asteroit kuşakları ve Truva kümeleri'], 'Dünya\'nın manyetik alanı tarafından tutulan yüksek enerjili parçacıklardan oluşan bu kuşaklar, 1958\'de Explorer 1 uydusunun verileriyle keşfedildi.'),
  ('1997\'de aylarca çıplak gözle görülen ve 20. yüzyılın en çok izlenen kuyruklu yıldızlarından biri olan kuyruklu yıldız hangisidir?', 'Hale-Bopp', ['Halley', 'Shoemaker-Levy 9', 'Encke'], 'Hale-Bopp, yaklaşık 18 ay boyunca çıplak gözle görülebilir kaldı; çekirdeği alışılmadık biçimde büyüktü.'),
  ('Jüpiter\'in çevresinde, Galileo uydularının çok içinde dolanan ve 1979\'da Voyager 1 tarafından keşfedilen sönük yapı nedir?', 'İnce bir halka sistemi', ['İkinci bir Büyük Kırmızı Leke', 'Bir asteroit kuşağı', 'Bir kara delik'], 'Jüpiter\'in halkaları çok ince toz parçacıklarından oluşur ve çok sönüktür; bu nedenle ancak uzay araçlarıyla keşfedilebildi.'),
  ('Plüton\'un 1930\'daki keşfi hangi gözlem yöntemine dayanıyordu?', 'Farklı gecelerde çekilen fotoğrafların karşılaştırılarak yer değiştiren noktanın aranması', ['Radyo sinyallerinin dinlenmesi', 'Uzay aracından gelen görüntülerin incelenmesi', 'Gökyüzüne lazer gönderilip yansımanın ölçülmesi'], 'Clyde Tombaugh, aynı gökyüzü bölgesinin günler arayla çekilmiş fotoğraf plakalarını hızla değiştirerek yıldızlara göre kayan sönük bir nokta aradı ve Plüton\'u buldu.'),
  ('Ay, Dünya çevresinde hangi yönde dolanır?', 'Dünya\'nın döndüğü yönde, batıdan doğuya', ['Doğudan batıya, Dünya\'nın dönüşünün tersine', 'Kuzeyden güneye, kutupların üzerinden geçerek', 'Yönünü her ay değiştirerek'], 'Ay, Dünya\'nın kuzey kutbunun üstünden bakıldığında saat yönünün tersine, yani Dünya\'nın dönüşüyle aynı yönde dolanır; bu yüzden yıldızlara göre her gece doğuya kayar.'),
  ('Dünya\'dan bakıldığında Ay ve Güneş\'in gökyüzünde aynı açısal büyüklükte görünmesi yaklaşık kaç derecedir?', '0,5°', ['5°', '15°', '0,05°'], 'Güneş ve Ay\'ın her biri yaklaşık yarım derece genişliğinde görünür; uzatılmış bir kolun ucundaki serçe parmak bile ikisini örtebilir.'),
  ('Mars yüzeyinde ilk kez başarıyla çalışan hareketli keşif aracı hangisidir?', 'Sojourner', ['Curiosity', 'Perseverance', 'Opportunity'], '1997\'de Mars Pathfinder göreviyle Mars\'a inen küçük Sojourner, Mars\'ta dolaşan ilk tekerlekli araç oldu.'),
  ('Perseverance keşif aracının Mars\'taki temel görevlerinden biri hangisidir?', 'Eski yaşam izlerini aramak ve örnek toplayıp saklamak', ['Mars\'a ilk astronotları taşımak', 'Mars\'ın uydularına inmek', 'Mars\'ın çekirdeğine kadar sondaj yapmak'], 'Perseverance, eskiden bir göl ve delta olan Jezero Krateri\'nde biyolojik izler arar ve ileride Dünya\'ya getirilmek üzere kaya örneklerini tüplerde saklar.'),
  ('Satürn\'ün uydusu Titan\'a inen Huygens aracı neyi başarmıştır?', 'Dış Güneş sisteminde bir uyduya yapılan ilk iniş', ['Titan\'dan örnek getirmek', 'Titan\'da yaşam bulmak', 'Titan\'ın okyanusunda yüzmek ve dalmak'], 'Huygens, 2005\'te Titan\'ın atmosferinden paraşütle inerek yüzeyden veri gönderdi; dış Güneş sisteminde bir cisme yapılan ilk iniş buydu.'),
  ('Titan\'ın kalın atmosferi ve düşük çekimi göz önüne alındığında, Titan\'ı keşfetmek için tasarlanan Dragonfly görevi hangi tür araç kullanacaktır?', 'Pervaneli uçan bir araç', ['Tekerlekli keşif aracı', 'Denizaltı', 'Yüzeyde sabit duran bir iniş platformu'], 'Titan\'da hava yoğun, çekim zayıf olduğundan uçmak Dünya\'dakinden kolaydır. Dragonfly, birçok pervanesiyle bir yerden ötekine uçarak farklı bölgeleri inceleyecek şekilde tasarlanmıştır.'),
  ('Elektromanyetik tayfta görünür ışıktan daha uzun dalga boylu bölgeler aşağıdakilerin hangisinde doğru sırayla verilmiştir?', 'Kızılötesi, mikrodalga, radyo', ['Morötesi, X ışını, gama ışını', 'Radyo, kızılötesi, mikrodalga', 'Gama ışını, morötesi, radyo'], 'Görünür ışıktan uzun dalga boylarına gidildikçe sırayla kızılötesi, mikrodalga ve radyo dalgaları gelir; kısa dalga tarafında ise morötesi, X ve gama ışınları bulunur.'),
  ('Bir gökbilimci, uzak bir gökadanın tayfındaki tanıdık hidrojen çizgilerini beklediğinden çok daha uzun dalga boylarında buluyor. Bunun en olası açıklaması nedir?', 'Gökada çok uzaktadır ve kozmolojik kırmızıya kayma büyüktür', ['Gökada bize hızla yaklaşmaktadır', 'Gökada hidrojen içermez', 'Teleskobun merceği kırıktır'], 'Evrenin genişlemesiyle uzak gökadaların ışığı uzar. Çizgilerin tanıdık dizilişi korunduğu için kaymanın miktarı ölçülebilir ve uzaklık hakkında bilgi verir.'),
  ('Yıldız tayflarında görülen soğurma çizgileri neden oluşur?', 'Yıldızın daha soğuk dış katmanlarındaki atomlar belirli dalga boylarını soğurur', ['Yıldızın önünden geçen gezegenler ışığı keser', 'Dünya\'nın Ay\'ı ışığı engeller', 'Yıldızın içindeki kara delikler ışığı yutar'], 'Yıldızın sıcak iç kısmından gelen sürekli ışık, daha soğuk atmosferden geçerken atomlarca belirli dalga boylarında soğurulur ve tayfta karanlık çizgiler bırakır.'),
  ('Güneş\'in ana koldaki toplam ömrünün yaklaşık ne kadar olduğu düşünülür?', 'Yaklaşık 10 milyar yıl', ['Yaklaşık 10 milyon yıl', 'Yaklaşık 100 milyon yıl', 'Yaklaşık 1 trilyon yıl'], 'Güneş yaklaşık 4,6 milyar yaşındadır ve ana kol ömrünün yarısına yakınını tamamlamıştır; kalan süre yaklaşık 5 milyar yıl kadardır.'),
  ('Güneş bir kırmızı deve dönüştüğünde Dünya\'yı hangi olayın beklediği düşünülür?', 'Okyanuslarının buharlaşması ve yüzeyin kavrulması', ['Dünya\'nın buz çağına girmesi', 'Dünya\'nın yeni bir yıldız olması', 'Dünya\'nın Güneş sisteminden fırlatılması'], 'Güneş genişleyip çok daha parlak hâle geldiğinde Dünya\'ya ulaşan enerji büyük ölçüde artar; okyanuslar aslında bundan çok önce, Güneş\'in yavaş parlaklaşmasıyla buharlaşmaya başlayacaktır.'),
  ('Bir açık kümenin yıldızlarının hepsinin bize yaklaşık aynı uzaklıkta olması, gökbilimcilere hangi kolaylığı sağlar?', 'Yıldızların görünür parlaklıklarını doğrudan karşılaştırabilmeyi', ['Yıldızların yaşlarının farklı olduğunu görmeyi', 'Yıldızların kütlelerini sıfır kabul etmeyi', 'Kümenin içinde gezegen olmadığını kanıtlamayı'], 'Yıldızlar aynı uzaklıktaysa görünür parlaklık farkları doğrudan ışıma gücü farklarını yansıtır; bu da H-R diyagramı çizmeyi ve kümeyi incelemeyi kolaylaştırır.'),
  ('Hubble sabiti hakkında hangisi doğrudur?', 'Gökadaların uzaklaşma hızı ile uzaklıkları arasındaki orantı sabitidir', ['Bir gökadanın kütlesini verir', 'Işık hızının başka bir adıdır', 'Bir yıldızın yaşını ölçer'], 'Hubble yasasında v = H₀ × d olarak yer alan H₀, evrenin bugünkü genişleme hızını anlatır; değeri genellikle km/s/Mpc biriminde verilir.'),
  ('Bir yıldızın ışıma gücü artarsa, çevresindeki yaşanabilir bölge nasıl değişir?', 'Yıldızdan daha uzağa kayar', ['Yıldıza daha çok yaklaşır', 'Hiç değişmez', 'Tamamen ortadan kalkar ve bir daha oluşmaz'], 'Daha güçlü bir yıldızın çevresinde aynı sıcaklığı bulmak için daha uzağa gitmek gerekir. Güneş zamanla parlaklaştıkça yaşanabilir bölge de yavaşça dışa doğru kaymaktadır.'),
  ('Mars bazen Güneş\'in yaşanabilir bölgesinin dış kenarına yakın sayılır. Buna karşın bugün yüzeyinde sıvı su bulunmamasının en önemli nedenlerinden biri hangisidir?', 'Atmosferinin çok ince olması', ['Güneş\'e çok yakın olması', 'Yüzeyinin tamamen demirden oluşması', 'Kendi ekseni çevresinde hiç dönmemesi'], 'Yaşanabilir bölgede olmak tek başına yetmez; sıvı suyun var olabilmesi için yeterli atmosfer basıncı ve sıcaklığı da gerekir. Mars\'ın ince atmosferi bu koşulları sağlayamaz.'),
  ('Spitzer Uzay Teleskobu hangi dalga boyu bölgesinde gözlem yapıyordu?', 'Kızılötesi', ['X ışını ve morötesi', 'Gama ışını', 'Radyo'], '2003-2020 yılları arasında çalışan Spitzer, NASA\'nın büyük gözlemevlerinden biriydi ve tozla örtülü yıldız oluşum bölgelerini ve ötegezegenleri kızılötesinde inceledi.'),
  ('James Webb Uzay Teleskobu\'nun büyük, çok katmanlı güneş kalkanının işlevi nedir?', 'Teleskobu Güneş, Dünya ve Ay\'ın ısısından koruyup çok soğuk tutmak', ['Teleskobu göktaşlarından korumak', 'Güneş ışığını toplayıp enerji üretmek', 'Teleskobun aynasını Güneş\'e doğru yansıtmak'], 'Tenis kortu büyüklüğündeki beş katmanlı kalkan, aynanın ve aygıtların yaklaşık −230 °C civarında kalmasını sağlar; böylece teleskobun kendi ısısı kızılötesi gözlemleri bozmaz.'),
  ('Hubble Uzay Teleskobu\'nun Dünya yörüngesinde bulunmasının, James Webb\'in ise çok uzaktaki L2 noktasında bulunmasının bir sonucu nedir?', 'Hubble\'a astronotlar bakım yapabildi, Webb\'e ise yapılamaz', ['Webb\'in görüntüleri Dünya\'ya ulaşamaz', 'Hubble hiç güneş ışığı almaz', 'Webb\'e her yıl astronotlar gider'], 'Hubble\'a uzay mekiğiyle beş bakım görevi düzenlendi. Yaklaşık 1,5 milyon km uzaktaki Webb\'e ise insanlı ulaşım mümkün olmadığından teleskop bakımsız çalışacak biçimde tasarlandı.'),
  ('Ay\'da bir gün (bir gündoğumundan ötekine) yaklaşık ne kadar sürer?', 'Yaklaşık 29,5 Dünya günü', ['Yaklaşık 24 saat', 'Yaklaşık 7 Dünya günü', 'Yaklaşık bir Dünya yılı, yani 365 gün'], 'Ay kendi ekseni çevresinde bir ayda döndüğü için Ay yüzeyindeki bir noktada Güneş yaklaşık 29,5 günde bir doğar.'),
  ('Bir uzay aracı Dünya\'dan Mars\'a gitmek için neden düz bir çizgi yerine kavisli bir yol izler?', 'Hem araç hem gezegenler Güneş\'in çekimi altında yörüngede hareket eder', ['Uzayda düz gitmek yasaktır', 'Mars sürekli yer değiştirmez', 'Roketler yalnızca sola dönebilir'], 'Fırlatılan araç Güneş çevresinde yeni bir yörüngeye girer. Yakıt tasarrufu için bu yörünge, aracı Mars\'ın aylar sonra bulunacağı noktaya ulaştıracak biçimde seçilir.'),
  ('Halkalı Güneş tutulması ile tam Güneş tutulması arasında Güneş\'in tacının görülmesi bakımından ne fark vardır?', 'Tam tutulmada taç görülür, halkalı tutulmada görülmez', ['İkisinde de taç açıkça görülür', 'Halkalı tutulmada taç daha parlak görülür', 'İkisinde de taç hiç görülmez ve gökyüzü değişmez'], 'Halkalı tutulmada Güneş\'in parlak kenarı açıkta kaldığı için gökyüzü yeterince kararmaz ve sönük taç görülemez; koruyucu süzgeç de her aşamada gereklidir.'),
];
